അബൂദാവുദ്(റ) പറയുന്നു: ചിലർ ഇപ്രകാരം പറഞ്ഞിരിക്കുന്നു: ഫറഅ് എന്നാൽ ഒട്ടകത്തിന്റെ കടിഞ്ഞൂലാണ്. അവർ അതിനെ അവരുടെ ദൈവങ്ങൾക്ക് വേണ്ടി അറുക്കുകയും ശേഷമതിനെ ഭക്ഷിക്കുകയും അതിന്റെ തോൽ മരത്തിൻമേലിടുകയും ചെയ്യും. അതീറത്തെന്നാൽ റജബ് മാസത്തിലെ ആദ്യത്തെ പത്തിലെ അറവാണ്. (ബു,ദ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['خ','د']::text[], array['ബു','ദ']::text[], null, null, 913, 913, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=4 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
