insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 1, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَا عَمِلَ آدَمِيٌّ مِنْ عَمَلٍ يَوْمَ النَّحْرِ أَحَبَّ إِلَى اللهِ مِنْ إِهْرَاقِ الدَّمِ، إِنَّهَا لَتَأْتِي يَوْمَ الْقِيَامَةِ بِقُرُونِهَا وَأَشْعَارِهَا وَأَظْلَافِهَا، وَأَنَّ الدَّمَ لَيَقَعُ مِنَ اللهِ بِمَكَانٍ قَبْلَ أَنْ يَقَعَ مِنَ الْأَرْضِ، فَطِيبُوا بِهَا نَفْسًا". حسن. (ت,جه)', 'ആഇശ(റ): നിശ്ചയം റസൂൽ(സ) പറഞ്ഞു: "അറവിനേക്കാൾ അല്ലാഹുവിന് ഇഷ്ടപ്പെട്ട മറ്റൊരു സൽകർമ്മവും ബലിദിനത്തിൽ ഒരു മനുഷ്യനും ചെയ്തിട്ടില്ല. നിശ്ചയം, അന്ത്യദിനത്തിൽ ആ മൃഗം അതിന്റെ കൊമ്പുകളും കുളമ്പുകളും രോമങ്ങളുമായി വരും. നിശ്ചയം രക്തം ഭൂമിയിൽ പതിക്കുന്നതിന് മുമ്പായി അല്ലാഹുവിങ്കൽ ഒരു സ്ഥാനത്ത് ആ രക്തം പതിക്കുന്നതാണ്. അതിനാൽ നിങ്ങളുടെ നഫ്സിനെ നിങ്ങൾ അതുകൊണ്ട് നന്നാക്കുക." ഹദീസ് ഹസനാണ്. (തു,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 889, 889, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=4 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 2, 'عَنْ زَيْدِ بْنِ أَرْقَمَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ أَصْحَابُ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: يَا رَسُولَ اللهِ، مَا هَذِهِ الْأَضَاحِيُّ؟ قَالَ: "سُنَّةُ أَبِيكُمْ إِبْرَاهِيمَ". قَالُوا: فَمَا لَنَا فِيهَا يَا رَسُولَ اللهِ؟ قَالَ: "بِكُلِّ شَعَرَةٍ حَسَنَةٌ". قَالُوا: فَالصُّوفُ يَا رَسُولَ اللهِ؟ قَالَ: "بِكُلِّ شَعَرَةٍ مِنَ الصُّوفِ حَسَنَةٌ". [ز: في إسناده متروك] (جه)', 'സൈദുബ്നു അർഖം(റ): റസൂൽ(സ)യുടെ അനുചരർ ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, എന്താണീ ഉള്ഹിയ്യത്? അവിടുന്ന് പറഞ്ഞു: "നിങ്ങളുടെ പിതാവായ ഇബ്രാഹീം(അ)ന്റെ ചര്യയാണത്." അവർ ചോദിച്ചു: എങ്കിൽ നമുക്കതിലെന്താണുള്ളത് തിരുദൂതരേ? അവിടന്ന് പറഞ്ഞു: "ഒരോ മുടിക്കും നന്മയുണ്ട്." അവർ ചോദിച്ചു: അപ്പോൾ ആട്ടിൻ രോമങ്ങളോ തിരുദൂതരേ? അവിടന്ന് പറഞ്ഞു: "ആട്ടിൻ രോമങ്ങളിൽനിന്നുള്ള ഓരോ മുടിക്കും നന്മയുണ്ട്." ഇതിന്റെ പരമ്പരയിൽ ഒരു ''മത്റൂക്'' ഉണ്ട്. (ജ)', 'زَيْدِ بْنِ أَرْقَمَ', 'സൈദുബ്നു അർഖം(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في إسناده متروك', null, 889, 889, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=4 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 3, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ كَانَ لَهُ سَعَةٌ وَلَمْ يُضَحِّ فَلَا يَقْرَبَنَّ مُصَلَّانَا". [ز: في إسناده ضعيف] (جه)', 'അബൂഹുറൈറ(റ): നിശ്ചയം റസൂൽ(സ) പറഞ്ഞു: " കഴിവുണ്ടായിട്ടും ഉള്ഹിയത്തറുക്കാത്തവൻ നമ്മുടെ നമസ്കാര സ്ഥലത്തേക്കടുക്കരുത്." ഇതിന്റെ പരമ്പരയിൽ ബലഹീനനുണ്ട്. (ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في إسناده ضعيف', null, 889, 889, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=4 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 4, 'عَنْ مُحَمَّدِ بْنِ سِيرِينَ قَالَ: سَأَلْتُ ابْنَ عُمَرَ - رَضِيَ اللهُ عَنْهُمَا - عَنِ الضَّحَايَا، أَوَاجِبَةٌ هِيَ؟ قَالَ: ضَحَّى رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَالْمُسْلِمُونَ مِنْ بَعْدِهِ، وَجَرَتْ بِهِ السُّنَّةُ. (ت,جه)', 'മുഹമ്മദുബ്നു സീരീൻ(റ): ഉള്ഹിയ്യത് നിർബന്ധമാണോ എന്ന് ഇബ്നുഉമർ(റ)വിനോട് ഞാൻ ചോദിച്ചു. അദ്ദേഹം പറഞ്ഞു: റസൂൽ(സ)യും അവിടുത്തെ ശേഷം മുസ്ലിംകളും ഉള്ഹിയ്യത്ത് അറുത്തിരിക്കുന്നു, അങ്ങനെയത് സുന്നത്തായി നടത്തപ്പെടുന്നു. (തു,ജ)', 'مُحَمَّدِ بْنِ سِيرِينَ قَالَ', 'മുഹമ്മദുബ്നു സീരീൻ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 889, 889, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=4 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 5, 'عَنْ مخنف بْنِ سُلَيْمٍ رَضِيَ اللهُ عَنْهُ قَالَ: كُنَّا وُقُوفًا عِنْدَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِعَرَفَةَ، فَقَالَ: "يَا أَيُّهَا النَّاسُ، إِنَّ عَلَى كُلِّ أَهْلِ بَيْتٍ فِي كُلِّ عَامٍ أُضْحِيَّةً وَعَتِيرَةً". أَتَدْرُونَ مَا الْعَتِيرَةُ؟ هِيَ الَّتِي يُسَمِّيهَا النَّاسُ الرَّجَبِيَّةَ. (د,ت,ن,جه)', 'മിഖ്നഫുബ്നു സുലൈം(റ): ഞങ്ങൾ റസൂൽ(സ)യോടൊത്ത് അറഫയിൽ നിൽക്കുകയായിരുന്നു, അപ്പോളവിടുന്ന് പറഞ്ഞു: "ഓ ജനങ്ങളേ, നിശ്ചയം ഓരോ കുടുംബത്തിനും എല്ലാ കൊല്ലവും ഉള്ഹിയ്യതും ''അതീറതും'' ബാധ്യതയാണ്." ''അതീറതെ''ന്നാൽ എന്താണെന്ന് നിങ്ങൾക്കറിയുമോ? ജനങ്ങൾ റജബിയ്യ(റജബ് മാസത്തിൽ ബലിയറുക്കൽ) എന്ന് വിളിക്കുന്നതു തന്നെയാണത്. (ദ,തു,ന,ജ)', 'مخنف بْنِ سُلَيْمٍ', 'മിഖ്നഫുബ്നു സുലൈം(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 890, 890, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=4 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 6, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَجُلًا سَأَلَهُ عَنِ الْأُضْحِيَّةِ، أَوَاجِبَةٌ هِيَ؟ فَقَالَ: ضَحَّى رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَالْمُسْلِمُونَ، فَأَعَادَهَا عَلَيْهِ، فَقَالَ: أَتَعْقِلُ؟ ضَحَّى رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَالْمُسْلِمُونَ. (ت,جه)', 'ഇബ്നുഉമർ(റ): ഉള്ഹിയ്യത് നിർബന്ധമാണോ എന്ന് ഒരാൾ അദ്ദേഹത്തോട് ചോദിച്ചു. അപ്പോഴദ്ദേഹം പറഞ്ഞു: റസൂൽ(സ)യും മുസ്ലിംകളും ഉള്ഹിയ്യത്തറുത്തിരിക്കുന്നു. അയാൾ വീണ്ടും അദ്ദേഹത്തോട് ചോദ്യം ആവർത്തിച്ചു. അപ്പോഴദ്ദേഹം ചോദിച്ചു: നിങ്ങൾക്കെന്താ ബുദ്ധിയില്ലേ? റസൂൽ(സ)യും മുസ്ലിംകളും ഉള്ഹിയ്യത്തറുത്തിരിക്കുന്നു. (തു,ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 890, 890, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=4 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 7, 'عَنْ عُمَرَ بْنِ الْخَطَّابِ رَضِيَ اللهُ عَنْهُ: أَنَّهُ صَلَّى الْعِيدَ يَوْمَ الْأَضْحَى قَبْلَ الْخُطْبَةِ، ثُمَّ خَطَبَ فَقَالَ: يَا أَيُّهَا النَّاسُ، إِنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَدْ نَهَاكُمْ عَنْ صِيَامِ هَذَيْنِ الْعِيدَيْنِ، أَمَّا أَحَدُهُمَا فَيَوْمُ فِطْرِكُمْ مِنْ صِيَامِكُمْ، وَأَمَّا الْآخَرُ فَيَوْمٌ تَأْكُلُونَ مِنْ نُسُكِكُمْ. (خ)', 'ഉമറുബ്നുൽ ഖത്വാബ്(റ): ബലിപെരുന്നാൾ ദിവസം ''ഖുത്വുബ''ക്ക് മുമ്പായി അദ്ദേഹം പെരുന്നാൾ നമസ്കാരം നിർവഹിച്ചു. പിന്നെ ഖുത്വുബ നിർവഹിച്ചുകൊണ്ട് അദ്ദേഹം പറഞ്ഞു: ഓ ജനങ്ങളേ, ഈ രണ്ട് ദിവസങ്ങളിൽ നിങ്ങൾ നോമ്പനുഷ്ഠിക്കൽ റസൂൽ(സ) നിരോധിച്ചിരിക്കുന്നു; അവയിലൊന്ന് നിങ്ങളുടെ നോമ്പ് കഴിഞ്ഞുള്ള ''ഫിത്വ്ർ'' ദിനമാണ് (ചെറിയ പെരുന്നാൾ), മറ്റേത് നിങ്ങൾ നിങ്ങളുടെ ബലി മാംസങ്ങളിൽ നിന്ന് ഭക്ഷിക്കുന്ന ദിനമാണ്(ബലിപെരുന്നാൾ). (ബു)', 'عُمَرَ بْنِ الْخَطَّابِ', 'ഉമറുബ്നുൽ ഖത്വാബ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 890, 890, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=4 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 8, 'عَنْ ثَوْبَانَ رَضِيَ اللهُ عَنْهُ قَالَ: ضَحَّى رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ ثُمَّ قَالَ: "يَا ثَوْبَانُ، أَصْلِحْ لَنَا لَحْمَ هَذِهِ الشَّاةِ". قَالَ: فَمَا زِلْتُ أُطْعِمُهُ مِنْهَا حَتَّى قَدِمْنَا الْمَدِينَةَ. (م,د)', 'സൗബാൻ(റ): റസൂൽ(സ) ഉള്ഹിയ്യത്തറുത്തിട്ട് പറഞ്ഞു: "ഓ സൗബാൻ, ഈ ആടിന്റെ മാംസം ഞങ്ങൾക്കുവേണ്ടി ശരിയാക്കിത്തരൂ." നിവേദകൻ പറയുന്നു: അങ്ങനെ ഞങ്ങൾ മദീനത്തെത്തുംവരെ തിരുമേനി(സ)യെ ഞാൻ അതിൽനിന്ന് ഭക്ഷിപ്പിച്ചുകൊണ്ടേയിരുന്നു. (മു,ദ)', 'ثَوْبَانَ', 'സൗബാൻ(റ)', null, null, array['م','د']::text[], array['മു','ദ']::text[], null, null, 890, 890, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=4 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 9, 'عَنْ عَلِيٍّ رَضِيَ اللهُ عَنْهُ: أَنَّهُ كَانَ يُضَحِّي بِكَبْشَيْنِ: أَحَدُهُمَا عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، وَالْآخَرُ عَنْ نَفْسِهِ، فَقِيلَ لَهُ؟ فَقَالَ: أَمَرَنِي بِهِ - يَعْنِي - النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَلَا أَدَعُهُ أَبَدًا. (د,ت)', 'അലി(റ): അദ്ദേഹം രണ്ട് ആടുകളെ ഉള്ഹിയ്യത്തറുക്കാറുണ്ടായിരുന്നു. ഒന്ന് നബി(സ)ക്ക് വേണ്ടിയും മറ്റൊന്ന് സ്വന്തത്തിന് വേണ്ടിയും. അപ്പോൾ അദ്ദേഹത്തോട് അതിനെക്കുറിച്ച് ചോദിക്കപ്പെട്ടു; അദ്ദേഹം പറഞ്ഞു: ഇപ്രകാരം ചെയ്യാൻ നബി(സ) എന്നോട് കൽപിച്ചിരിക്കുന്നു. അതിനാൽ ഞാനതൊരിക്കലും ഒഴിവാക്കുന്നതല്ല. (ദ,തു)', 'عَلِيٍّ', 'അലി(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 890, 891, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=4 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 10, 'عَنْ حَنَشٍ رَضِيَ اللهُ عَنْهُ قَالَ: رَأَيْتُ عَلِيًّا رَضِيَ اللهُ عَنْهُ يُضَحِّي بِكَبْشَيْنِ، فَقُلْتُ لَهُ: مَا هَذَا؟ فَقَالَ: إِنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَوْصَانِي أَنْ أُضَحِّيَ عَنْهُ. (د,ت)', 'ഹനശ്(റ): അലി(റ) രണ്ട് ആടുകളെ ഉള്ഹിയ്യത്തറുക്കുന്നതായി ഞാൻ കണ്ടു. അപ്പോൾ ഞാനദ്ദേഹത്തോട് ചോദിച്ചു: എന്താണിത്? അപ്പോഴദ്ദേഹം പറഞ്ഞു: നിശ്ചയം റസൂൽ(സ)ക്കുവേണ്ടി ഉള്ഹിയ്യത്തറുക്കാൻ അവിടുന്നെന്നോട് വസ്വിയ്യത്ത് ചെയ്തിരിക്കുന്നു. (ദ,തു)', 'حَنَشٍ', 'ഹനശ്(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 891, 891, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=4 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 11, 'عَنْ أُمِّ سَلَمَةَ رَضِيَ اللهُ عَنْهَا، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ رَأَى هِلَالَ ذِي الْحِجَّةِ، فَأَرَادَ أَنْ يُضَحِّيَ، فَلَا يَأْخُذْ مِنْ شَعْرِهِ وَلَا مِنْ أَظْفَارِهِ حَتَّى يُضَحِّيَ". وَفِي رِوَايَةٍ قَالَ: "مَنْ أَرَادَ أَنْ يُضَحِّيَ، فَلَا يَقْلِمْ مِنْ أَظْفَارِهِ، وَلَا يَحْلِقْ شَيْئًا مِنْ شَعْرِهِ، فِي عَشْرِ الْأُوَلِ مِنْ ذِي الْحِجَّةِ". وَفِي رِوَايَةٍ قَالَ: "إِذَا دَخَلَتِ الْعَشْرُ، فَأَرَادَ أَحَدُكُمْ أَنْ يُضَحِّيَ، فَلَا يَمَسَّ مِنْ شَعْرِهِ وَلَا مِنْ بَشَرِهِ شَيْئًا". (م,د,ت,ن,جه)', 'ഉമ്മുസലമ(റ): നബി(സ) പറഞ്ഞു: "ഒരാൾ ദുൽഹിജ്ജയുടെ മാസപ്പിറവി കാണുകയും ഉള്ഹിയ്യത്ത് അറുക്കാൻ ഉദ്ദേശിക്കുകയും ചെയ്താൽ ഉള്ഹിയ്യത്തറുക്കുന്നതുവരെ അവൻ തന്റെ നഖങ്ങളോ രോമങ്ങളോ നീക്കരുത്." മറ്റൊരു നിവേദനം: നബി(സ) പറഞ്ഞു: "ഒരാൾ ഉള്ഹിയ്യത്തറുക്കാൻ ഉദ്ദേശിച്ചാൽ ദുൽഹിജ്ജ മാസത്തിലെ ആദ്യത്തെ പത്തു ദിവസം തന്റെ നഖങ്ങൾ വെട്ടുകയോ രോമങ്ങൾ വടിക്കുകയോ ചെയ്യരുത്." മറ്റൊരു നിവേദനം: അവിടുന്ന് പറഞ്ഞു: "പത്ത് (ദിവസങ്ങൾ) കടന്നുവരികയും നിങ്ങളിലൊരാൾ ഉള്ഹിയ്യത്തറുക്കാൻ ഉദ്ദേശിക്കുകയും ചെയ്താൽ അയാൾ തന്റെ രോമങ്ങളിൽ നിന്നോ തൊലിയിൽ നിന്നോ ഒന്നിനെയും തൊടരുത്." (മു,ദ,തു,ന,ജ)', 'أُمِّ سَلَمَةَ', 'ഉമ്മുസലമ(റ)', null, null, array['م','د','ت','ن','جه']::text[], array['മു','ദ','തു','ന','ജ']::text[], null, null, 891, 891, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=4 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=4 and b.book_no=17 and h.hadith_no=11), 1, 'وَفِي رِوَايَةٍ قَالَ: "مَنْ أَرَادَ أَنْ يُضَحِّيَ، فَلَا يَقْلِمْ مِنْ أَظْفَارِهِ، وَلَا يَحْلِقْ شَيْئًا مِنْ شَعْرِهِ، فِي عَشْرِ الْأُوَلِ مِنْ ذِي الْحِجَّةِ".', 'മറ്റൊരു നിവേദനം: നബി(സ) പറഞ്ഞു: "ഒരാൾ ഉള്ഹിയ്യത്തറുക്കാൻ ഉദ്ദേശിച്ചാൽ ദുൽഹിജ്ജ മാസത്തിലെ ആദ്യത്തെ പത്തു ദിവസം തന്റെ നഖങ്ങൾ വെട്ടുകയോ രോമങ്ങൾ വടിക്കുകയോ ചെയ്യരുത്."');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=4 and b.book_no=17 and h.hadith_no=11), 2, 'وَفِي رِوَايَةٍ قَالَ: "إِذَا دَخَلَتِ الْعَشْرُ، فَأَرَادَ أَحَدُكُمْ أَنْ يُضَحِّيَ، فَلَا يَمَسَّ مِنْ شَعْرِهِ وَلَا مِنْ بَشَرِهِ شَيْئًا". (م,د,ت,ن,جه)', 'മറ്റൊരു നിവേദനം: അവിടുന്ന് പറഞ്ഞു: "പത്ത് (ദിവസങ്ങൾ) കടന്നുവരികയും നിങ്ങളിലൊരാൾ ഉള്ഹിയ്യത്തറുക്കാൻ ഉദ്ദേശിക്കുകയും ചെയ്താൽ അയാൾ തന്റെ രോമങ്ങളിൽ നിന്നോ തൊലിയിൽ നിന്നോ ഒന്നിനെയും തൊടരുത്." (മു,ദ,തു,ന,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 12, 'عَنْ أُمِّ سَلَمَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ كَانَ لَهُ ذِبْحٌ يَذْبَحُهُ: فَإِذَا أُهِلَّ هِلَالُ ذِي الْحِجَّةِ، فَلَا يَأْخُذَنَّ مِنْ شَعْرِهِ وَلَا مِنْ أَظْفَارِهِ شَيْئًا، حَتَّى يُضَحِّيَ". (م,د)', 'ഉമ്മുസലമ(റ): നബി(സ) പറഞ്ഞു: "ആർക്കെങ്കിലും അറുക്കാനുള്ള അറവുമൃഗമുണ്ടെങ്കിൽ, ദുൽഹിജ്ജ മാസം പിറന്നാൽ ഉള്ഹിയ്യത്തറുക്കുന്നതുവരെ അവൻ അവന്റെ രോമങ്ങളോ നഖങ്ങളോ തീർച്ചയായും നീക്കരുത്." (മു,ദ)', 'أُمِّ سَلَمَةَ', 'ഉമ്മുസലമ(റ)', null, null, array['م','د']::text[], array['മു','ദ']::text[], null, null, 891, 891, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=4 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 13, 'عَنْ عَبْدِ اللهِ بْنِ عَمْرِو بْنِ الْعَاصِ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ لِرَجُلٍ: "أُمِرْتُ بِيَوْمِ الْأَضْحَى عِيدًا، جَعَلَهُ اللهُ عَزَّ وَجَلَّ لِهَذِهِ الْأُمَّةِ". فَقَالَ الرَّجُلُ: أَرَأَيْتَ إِنْ لَمْ أَجِدْ إِلَّا مَنِيحَةً أُنْثَى، أَفَأُضَحِّي بِهَا؟ قَالَ: "لَا، وَلَكِنْ تَأْخُذُ مِنْ شَعْرِكَ، وَتُقَلِّمُ أَظْفَارَكَ، وَتَقُصُّ شَارِبَكَ، وَتَحْلِقُ عَانَتَكَ، فَذَلِكَ تَمَامُ أُضْحِيَّتِكَ عِنْدَ اللهِ عَزَّ وَجَلَّ". (د,ن)', 'അബ്ദുല്ലാഹിബ്നു അംറുബ്നുൽ ആസ്(റ): നിശ്ചയം, റസൂൽ(സ) ഒരാളോട് പറഞ്ഞു: "ഈ സമുദായത്തിനുവേണ്ടി അല്ലാഹു നിശ്ചയിച്ച പെരുന്നാളായി ബലിദിനം കൊണ്ടാടാൻ എന്നോട് കൽപിക്കപ്പെട്ടിരിക്കുന്നു." അപ്പോഴദ്ദേഹം ചോദിച്ചു: പാൽ നൽകുന്ന ഒരു പെണ്ണാടല്ലാതെ . മറ്റൊന്നും എനിക്ക് ലഭിച്ചില്ലെങ്കിൽ ഞാനെന്താണു ചെയ്യേണ്ടത്, ഞാനതിനെ ബലിയറുക്കണോ? അവിടുന്ന് പറഞ്ഞു: "വേണ്ട, പക്ഷേ നീ നിന്റെ രോമങ്ങൾ കളയുകയും നഖം വെട്ടുകയും മീശ വെട്ടുകയും ഗുഹ്യരോമം വടിക്കുകയും ചെയ്യണം. അല്ലാഹുവിങ്കൽ അതാണ് നിന്റെ പരിപൂർണ ഉള്ഹിയ്യത്" (ദ,ന)', 'عَبْدِ اللهِ بْنِ عَمْرِو بْنِ الْعَاصِ', 'അബ്ദുല്ലാഹിബ്നു അംറുബ്നുൽ ആസ്(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 891, 892, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=4 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 14, 'عَنْ جَابِرِ بْنِ عَبْدِ اللهِ رَضِيَ اللهُ عَنْهُمَا قَالَ: ذَبَحَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَوْمَ الذَّبْحِ كَبْشَيْنِ أَقْرَنَيْنِ أَمْلَحَيْنِ مُوجَأَيْنِ، فَلَمَّا وَجَّهَهُمَا قَالَ: "إِنِّي وَجَّهْتُ وَجْهِيَ لِلَّذِي فَطَرَ السَّمَوَاتِ وَالْأَرْضَ، عَلَى مِلَّةِ إِبْرَاهِيمَ حَنِيفًا وَمَا أَنَا مِنَ الْمُشْرِكِينَ، إِنَّ صَلَاتِي وَنُسُكِي وَمَحْيَايَ وَمَمَاتِي لِلَّهِ رَبِّ الْعَالَمِينَ، لَا شَرِيكَ لَهُ وَبِذَلِكَ أُمِرْتُ وَأَنَا مِنَ الْمُسْلِمِينَ، اللَّهُمَّ مِنْكَ وَلَكَ، وَعَنْ مُحَمَّدٍ وَأُمَّتِهِ، بِاسْمِ اللهِ وَاللهُ أَكْبَرُ". ثُمَّ ذَبَحَ. (د,ت,جه)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): കൊമ്പുകളുള്ളതും കറുപ്പും വെളുപ്പും നിറങ്ങൾ കലർന്നതും വൃഷ്ണങ്ങൾ ഉടക്കപ്പെട്ടതുമായ രണ്ട് കൊറ്റനാടുകളെ അറവുദിവസം നബി(സ) അറുത്തു. അവ രണ്ടിന്റെയും മുഖം തിരിച്ചപ്പോൾ അവിടുന്നിപ്രകാരം ഉരുവിട്ടു: "ആകാശങ്ങളെയും ഭൂമിയെയും സൃഷ്ടിച്ചവനിലേക്ക് ഞാനെന്റെ മുഖം തിരിച്ചിരിക്കുന്നു, നേരാംവിധം ഇബ്രാഹീം(അ)ന്റെ സമുദായത്തിലായിക്കൊണ്ട്. ഞാൻ ബഹുദൈവാരാധകരിൽ പെട്ടവനല്ല. നിശ്ചയം, എന്റെ നമസ്കാരവും എന്റെ ആരാധനകളും എന്റെ ജീവിതവും മരണവും ലോക രക്ഷിതാവായ അല്ലാഹുവിന്ന് വേണ്ടിയാണ്. അവനൊരു പങ്കുകാരുമില്ല, അതാണ് ഞാൻ കൽപിക്കപ്പെട്ടിരിക്കുന്നത്. ഞാൻ മുസ്ലിംകളിൽ പെട്ടവനാണ്. അല്ലാഹുവേ, നിന്നിൽ നിന്നും, നിനക്ക് വേണ്ടിയും, മുഹമ്മദിന്റെ(സ)യും അവിടുത്തെ സമുദായത്തിന്റയും പേരിൽ (ഞാൻ അറുക്കുന്നു). അല്ലാഹുവിന്റെ നാമംകൊണ്ട് ഞാൻ തുടങ്ങുന്നു. അല്ലാഹുവാണ് ഏറ്റവും വലിയവൻ." പിന്നെയവിടുന്ന് അറുത്തു. (ദ,തു,ജ)', 'جَابِرِ بْنِ عَبْدِ اللهِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 892, 892, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=7 where b.volume_id=4 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 15, 'عَنْ أَبِي سَعِيدٍ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللهِ يُضَحِّي بِكَبْشٍ أَقْرَنَ فَحِيلٍ، يَنْظُرُ فِي سَوَادٍ، وَيَأْكُلُ فِي سَوَادٍ، وَيَمْشِي فِي سَوَادٍ. (د,ت,ن,جه)', 'അബൂസഈദ്(റ): കാലുകളും വയറിന്റെ ഭാഗവും കണ്ണുകളുടെ ചുറ്റുഭാഗവും കറുത്ത നിറമുള്ളതും കൊമ്പുള്ളതുമായ കൊറ്റനാടിനെ റസൂൽ(സ) ഉള്ഹിയ്യത്തറുക്കാറുണ്ടായിരുന്നു. (ദ,തു,ന,ജ)', 'أَبِي سَعِيدٍ', 'അബൂസഈദ്(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 892, 892, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=7 where b.volume_id=4 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 16, 'عَنْ عَائِشَةَ وَعَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا أَرَادَ أَنْ يُضَحِّيَ اشْتَرَى كَبْشَيْنِ عَظِيمَيْنِ سَمِينَيْنِ أَقْرَنَيْنِ أَمْلَحَيْنِ مَوْجُوءَيْنِ، فَذَبَحَ أَحَدَهُمَا عَنْ أُمَّتِهِ، لِمَنْ شَهِدَ لِلَّهِ بِالتَّوْحِيدِ وَشَهِدَ لَهُ بِالْبَلَاغِ، وَذَبَحَ الْآخَرَ عَنْ مُحَمَّدٍ وَعَنْ آلِ مُحَمَّدٍ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. [ز: في إسناده مختلف فيه] (جه)', 'ആഇശ(റ)യും അബൂഹുറൈറ(റ)വും നിവേദനം ചെയ്യുന്നു: നിശ്ചയം, റസൂൽ(സ) ഉള്ഹിയ്യത്തറുക്കാൻ ഉദ്ദേശിച്ചാൽ കൊമ്പുള്ളതും, തടിച്ചതും, കറുപ്പും വെളുപ്പും നിറങ്ങൾ കലർന്നതും വൃഷ്ണങ്ങൾ ഉടക്കപ്പെട്ടതുമായ വലിയ രണ്ട് ആടുകളെ വാങ്ങുമായിരുന്നു. അങ്ങനെ അവയിലൊന്നിനെ, തൗഹീദ് കൊണ്ട് അല്ലാഹുവിന് സാക്ഷ്യം വഹിക്കുകയും പ്രബോധന ദൗത്യ നിർവഹണംകൊണ്ട് അവിടുത്തേക്ക് സാക്ഷ്യം വഹിക്കുകയും ചെയ്ത അവിടുത്തെ സമുദായത്തിന് വേണ്ടിയും, മറ്റേതിനെ മുഹമ്മദ്(സ)ക്കും അവിടുത്തെ കുടുംബത്തിന് വേണ്ടിയും അറുക്കുമായിരുന്നു. ഇതിന്റെ പരമ്പരയിൽ അഭിപ്രായഭിന്നതയുള്ള നിവേദകനുണ്ട്. (ജ)', 'عَائِشَةَ وَعَنْ أَبِي هُرَيْرَةَ', 'ആഇശ(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في إسناده مختلف فيه', null, 892, 893, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=7 where b.volume_id=4 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 17, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ قَالَ: ضَحَّى رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِكَبْشَيْنِ أَمْلَحَيْنِ أَقْرَنَيْنِ، ذَبَحَهُمَا بِيَدِهِ، وَسَمَّى وَكَبَّرَ، وَوَضَعَ رِجْلَهُ عَلَى صِفَاحِهِمَا. وَفِي رِوَايَةٍ قَالَ: خَطَبَنَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَوْمَ أَضْحًى، وَانْكَفَأَ إِلَى كَبْشَيْنِ أَمْلَحَيْنِ فَذَبَحَهُمَا. (ق,د,ت,جه)', 'അനസ്(റ): റസൂൽ(സ) കൊമ്പുകളുള്ളതും കറുപ്പും വെളുപ്പും കലർന്ന നിറമുള്ളതുമായ രണ്ട് ആടുകളെ അറുത്തു. അവിടുന്ന് അവ രണ്ടിനെയും തന്റെ കരംകൊണ്ട് അറുക്കുകയും ബിസ്മി ചൊല്ലുകയും തക്ബീർ ചൊല്ലുകയും അവയുടെ കവിളിൽ തന്റെ കാല് വെക്കുകയും ചെയ്തു. മറ്റൊരു നിവേദനം: ബലിദിനത്തിൽ റസൂൽ(സ) ഞങ്ങളോട് ഖുത്വുബ നടത്തുകയും കറുപ്പും വെളുപ്പും കലർന്ന രണ്ട് ആടുകളിലേക്ക് തിരിഞ്ഞ് അവയെ അറുക്കുകയും ചെയ്തു. (ബു,മു,ദ,തു,ജ)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['ق','د','ت','جه']::text[], array['ബു','മു','ദ','തു','ജ']::text[], null, null, 893, 893, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=7 where b.volume_id=4 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=4 and b.book_no=17 and h.hadith_no=17), 1, 'وَفِي رِوَايَةٍ قَالَ: خَطَبَنَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَوْمَ أَضْحًى، وَانْكَفَأَ إِلَى كَبْشَيْنِ أَمْلَحَيْنِ فَذَبَحَهُمَا. (ق,د,ت,جه)', 'മറ്റൊരു നിവേദനം: ബലിദിനത്തിൽ റസൂൽ(സ) ഞങ്ങളോട് ഖുത്വുബ നടത്തുകയും കറുപ്പും വെളുപ്പും കലർന്ന രണ്ട് ആടുകളിലേക്ക് തിരിഞ്ഞ് അവയെ അറുക്കുകയും ചെയ്തു. (ബു,മു,ദ,തു,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 18, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَمَرَ بِكَبْشٍ أَقْرَنَ، يَطَأُ فِي سَوَادٍ وَيَنْظُرُ فِي سَوَادٍ وَيَبْرُكُ فِي سَوَادٍ، فَأُتِيَ بِهِ فَضَحَّى بِهِ، فَقَالَ: "يَا عَائِشَةُ، هَلُمِّي الْمُدْيَةَ". ثُمَّ قَالَ: "اشْحَذِيهَا بِحَجَرٍ". فَفَعَلْتُ، فَأَخَذَهَا، وَأَخَذَ الْكَبْشَ فَأَضْجَعَهُ وَذَبَحَهُ، وَقَالَ: "بِسْمِ اللهِ، اللَّهُمَّ تَقَبَّلْ مِنْ مُحَمَّدٍ وَآلِ مُحَمَّدٍ وَمِنْ أُمَّةِ مُحَمَّدٍ". ثُمَّ ضَحَّى بِهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. (م,د)', 'ആഇശ(റ): നിശ്ചയം, കൊമ്പുകളുള്ളതും കാലുകളും വയറിന്റെ ഭാഗവും കണ്ണുകളുടെ ചുറ്റുഭാഗവും കറുത്ത നിറമുള്ളതുമായ കൊറ്റനാടിനെ കൊണ്ടുവരാൻ നബി(സ) കൽപിച്ചു. അപ്പോളത് കൊണ്ടുവരപ്പെടുകയും അവിടുന്നതിനെ ബലിയറുക്കുകയും ചെയ്തു. അന്നേരം അവിടുന്ന് പറഞ്ഞു: "ഓ ആഈശാ, കത്തി കൊണ്ടുവരൂ." പിന്നെയവിടന്ന് പറഞ്ഞു: "ഒരു കല്ലുകൊണ്ട് നീയത് മൂർച്ച കൂട്ടുക." അപ്പോൾ മഹതി അപ്രകാരം ചെയ്തു. തിരുമേനി(സ) കത്തി വാങ്ങുകയും ആടിനെ പിടിച്ച് കിടത്തുകയും അതിനെ അറുക്കുകയും ചെയ്തു. അവിടന്ന് "അല്ലാഹുവിന്റെ നാമംകൊണ്ട് ഞാൻ തുടങ്ങുന്നു, അല്ലാഹുവേ, മുഹമ്മദ്(സ)യിൽനിന്നും മുഹമ്മദ്(സ)യുടെ കുടുംബത്തിൽ നിന്നും മുഹമ്മദ്(സ)യുടെ ഉമ്മതിൽ നിന്നും നീ സ്വീകരിക്കേണമേ." എന്ന് പറയുകയും പിന്നെയതിനെ ബലിയറുക്കുകയും ചെയ്തു. (മു,ദ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['م','د']::text[], array['മു','ദ']::text[], null, null, 893, 893, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=7 where b.volume_id=4 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 19, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ نَحَرَ سَبْعَ بَدَنَاتٍ بِيَدِهِ قِيَامًا، وَضَحَّى بِالْمَدِينَةِ بِكَبْشَيْنِ أَقْرَنَيْنِ أَمْلَحَيْنِ. (خ,د)', 'അനസ്(റ): നിശ്ചയം, നബി(സ) എഴുന്നേറ്റുനിന്നുകൊണ്ട് ഏഴ് ഒട്ടകങ്ങളെ സ്വന്തം കൈകൊണ്ട് അറുത്തു. മദീനയിൽ വെച്ച്, കൊമ്പുകളുള്ളതും കറുപ്പും വെളുപ്പും നിറങ്ങൾ കലർന്നതുമായ രണ്ട് കൊറ്റനാടുകളെ അവിടുന്ന് ഉള്ഹിയ്യത്തറുക്കുകയും ചെയ്തു. (ബു,ദ)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['خ','د']::text[], array['ബു','ദ']::text[], null, null, 893, 893, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=7 where b.volume_id=4 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 20, 'عَنْ يُونُسَ بْنِ مَيْسَرَةَ بْنِ حَلْبَسٍ قَالَ: خَرَجْتُ مَعَ أَبِي سَعِيدٍ الزُّرَقِيِّ رَضِيَ اللهُ عَنْهُ - صَاحِبِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ - إِلَى شِرَاءِ الضَّحَايَا. قَالَ يُونُسُ: فَأَشَارَ أَبُو سَعِيدٍ إِلَى كَبْشٍ أَدْغَمَ، لَيْسَ بِالْمُرْتَفِعِ وَلَا الْمُتَضِعِ فِي جِسْمِهِ، فَقَالَ لِي: اشْتَرِ لِي هَذَا. كَأَنَّهُ شَبَّهَهُ بِكَبْشِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. (جه)', 'യൂനുസുബ്നു മൈസറതുബ്നി ഹൽബസ്(റ): നബി(സ)യുടെ അനുചരനായ അബൂസഈദിസ്സുറഖി(റ)വിന്റെ കൂടെ ബലിമൃഗങ്ങൾ വാങ്ങാനായി ഞാൻ പോയി. യുനുസ്(റ) പറയുന്നു: അപ്പോൾ, ശരീരം ഉയരം കൂടിയതോ കുറഞ്ഞതോ അല്ലാത്ത, ചെവിയുടെയും താടയുടെയും ഭാഗത്ത് കറുപ്പ് നിറമുള്ള ഒരു കൊറ്റനാടിനെ ചൂണ്ടിക്കൊണ്ട് അബൂസഇൗദ്(റ) എന്നോട് പറഞ്ഞു: എനിക്കുവേണ്ടി ഇതിനെ വാങ്ങു. അത് റസൂൽ(സ)യുടെ ആടിനോട് സാദൃശ്യമുള്ളതായി അദ്ദേഹം മനസ്സിലാക്കിയെന്ന് തോന്നുന്നു. (ജ)', 'يُونُسَ بْنِ مَيْسَرَةَ بْنِ حَلْبَسٍ قَالَ', 'യൂനുസുബ്നു മൈസറതുബ്നി ഹൽബസ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 893, 894, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=7 where b.volume_id=4 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 21, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: لَقَدْ رَأَيْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَذْبَحُ أُضْحِيَّتَهُ بِيَدِهِ، وَاضِعًا قَدَمَهُ عَلَى صِفَاحِهَا. (جه)', 'അനസുബ്നു മാലിക്(റ): നിശ്ചയം, റസൂൽ(സ) അവിടുത്തെ ബലിമൃഗത്തെ അതിന്റെ കവിളിൽ തന്റെ കാല് വെച്ചുകൊണ്ട് അവിടുത്തെ കൈകൊണ്ട് അറുക്കുന്നതായി ഞാൻ കണ്ടു. (ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 894, 894, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=4 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 22, 'عَنْ سَعِيدِ بْنِ عَائِذٍ رَضِيَ اللهُ عَنْهُ، مُؤَذِّنِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ ذَبَحَ أُضْحِيَّتَهُ عِنْدَ طَرَفِ الزُّقَاقِ - طَرِيقِ بَنِي زُرَيْقٍ - بِيَدِهِ، بِشَفْرَةٍ. (جه)', 'സഈദുബ്നു ആഇദ്(റ) - നബി(സ)യുടെ മുഅദ്ദിൻ -: നിശ്ചയം, നബി(സ) അവിടുത്തെ ബലിമൃഗത്തെ ത്വർഫുസ്സുഖാഖ് - ബനൂസുറൈഖ് ഗോത്രക്കാരുടെ വഴി - എന്ന സ്ഥലത്തുവെച്ച് അവിടുത്തെ കൈകൾ കൊണ്ട് ഒരു വീതിയുള്ള കത്തി ഉപയോഗിച്ച് അറുത്തു. (ജ)', 'سَعِيدِ بْنِ عَائِذٍ', 'സഈദുബ്നു ആഇദ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 894, 894, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=4 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 23, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُضَحِّي بِكَبْشَيْنِ أَمْلَحَيْنِ أَقْرَنَيْنِ، وَكَانَ يُسَمِّي وَيُكَبِّرُ، وَلَقَدْ رَأَيْتُهُ يَذْبَحُهُمَا بِيَدِهِ، وَاضِعًا رِجْلَهُ عَلَى صِفَاحِهِمَا. (ق,ن,جه)', 'അനസുബ്നു മാലിക്(റ): റസൂൽ(സ) കൊമ്പുള്ളതും കറുപ്പും വെളുപ്പും കലർന്നതുമായ രണ്ട് കൊറ്റനാടുകളെ ഉള്ഹിയ്യത്തറുക്കുമായിരുന്നു. അവിടുന്ന് ബിസ്മിയും തക്ബീറും ചൊല്ലുമായിരുന്നു. നിശ്ചയം, അവിടുന്ന് അവയുടെ കവിളുകളിൽ തന്റെ കാലുവെച്ച് സ്വന്തം കൈകൊണ്ട് അവ രണ്ടിനെയും അറുക്കുന്നതായി ഞാൻ കണ്ടിട്ടുണ്ട്. (ബു,മു,ന,ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['ق','ن','جه']::text[], array['ബു','മു','ന','ജ']::text[], null, null, 894, 894, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=4 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 24, 'عَنْ جَابِرِ بْنِ عَبْدِ اللهِ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ نَحَرَ بَعْضَ بُدْنِهِ بِيَدِهِ، وَنَحَرَ بَعْضَهَا غَيْرُهُ. (ن)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): നിശ്ചയം, റസൂൽ(സ)യുടെ ഒട്ടകങ്ങളിൽ ചിലതിനെ അവിടുന്ന് സ്വന്തമായി അറുക്കുകയും ചിലതിനെ മറ്റുള്ളവർ അറുക്കുകയും ചെയ്തു. (ന)', 'جَابِرِ بْنِ عَبْدِ اللهِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 894, 894, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=4 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 25, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: أَقَامَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِالْمَدِينَةِ عَشْرَ سِنِينَ يُضَحِّي. (ت)', 'ഇബ്നുഉമർ(റ): ഉള്ഹിയ്യത്തറുക്കുന്നവരായി പത്ത് കൊല്ലം റസൂൽ(സ) മദീനയിൽ താമസിച്ചു. (തു)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 894, 894, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=4 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 26, 'عَنْ هِلَالِ بْنِ أَبِي هِلَالٍ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "يَجُوزُ الْجَذَعُ مِنَ الضَّأْنِ أُضْحِيَّةً". [ز: في سنده مجهول] (جه)', 'ഹിലാലുബ്നു അബീഹിലാൽ(റ): നിശ്ചയം, റസൂൽ(സ) പറഞ്ഞു: "ബലിമൃഗമായി ചെമ്മരിയാടുകളിലെ പ്രായം കുറഞ്ഞവ അനുവദനീയമാണ്." ഇതിന്റെ പരമ്പരയിൽ അജ്ഞാതനായ ഒരു നിവേദകനുണ്ട്. (ജ)', 'هِلَالِ بْنِ أَبِي هِلَالٍ', 'ഹിലാലുബ്നു അബീഹിലാൽ(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في سنده مجهول', null, 895, 895, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=4 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 27, 'عَنْ كُلَيْبِ بْنِ شِهَابٍ الْجَرْمِيِّ قَالَ: كُنَّا مَعَ رَجُلٍ مِنْ أَصْحَابِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُقَالُ لَهُ مُجَاشِعٌ، مِنْ بَنِي سُلَيْمٍ، فَعَزَّتِ الْغَنَمُ، فَأَمَرَ مُنَادِيًا فَنَادَى: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يَقُولُ: "إِنَّ الْجَذَعَ يُوفِي مِمَّا تُوُفِّيَ مِنْهُ الثَّنِيَّةُ". (د,جه)', 'കുലൈബുബ്നു ശിഹാബിൽ ജർമി(റ): ഒരിക്കൽ ഞങ്ങൾ, ബനൂസുലൈം ഗോത്രക്കാരനായ, മുജാശഅ് എന്ന് വിളിക്കപ്പെടുന്ന, റസൂൽ(സ)യുടെ അനുചരരിൽപെട്ട ഒരാളോടൊപ്പമായിരുന്നു. അപ്പോൾ ആടുകൾ വളരെ വിരളമായിരുന്നു. അപ്പോഴദ്ദേഹം ഒരാളോടിപ്രകാരം വിളിച്ചുപറയാൻ കൽപിച്ചു: നിശ്ചയം, റസൂൽ(സ) പറയാറുണ്ടായിരുന്നു: "ആറ് വയസ്സുള്ള ഒട്ടകം മതിയാകുന്നിടത്തെല്ലാം പ്രായം കുറഞ്ഞ ചെമ്മരിയാട് മതിയാകുന്നതാണ്." (ദ,ജ)', 'كُلَيْبِ بْنِ شِهَابٍ الْجَرْمِيِّ قَالَ', 'കുലൈബുബ്നു ശിഹാബിൽ ജർമി(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 895, 895, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=4 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 28, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا تَذْبَحُوا إِلَّا مُسِنَّةً، إِلَّا أَنْ يَعْسُرَ عَلَيْكُمْ، فَتَذْبَحُوا جَذَعَةً مِنَ الضَّأْنِ". (م,د,ن,جه)', 'ജാബിർ(റ): റസൂൽ(സ) പറഞ്ഞു: "ലഭ്യമല്ലെങ്കിലൊഴികെ പല്ലുകൾ മുളച്ച് വലുതായ ഒട്ടകമല്ലാത്തതിനെ നിങ്ങൾ അറുക്കരുത്. അങ്ങനെയെങ്കിൽ നിങ്ങൾ പ്രായം കുറഞ്ഞ ചെമ്മരിയാടിനെ അറുക്കുക." (മു,ദ,ന,ജ)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['م','د','ن','جه']::text[], array['മു','ദ','ന','ജ']::text[], null, null, 895, 895, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=4 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 29, 'عَنْ زَيْدِ بْنِ خَالِدٍ الْجُهَنِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: قَسَمَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي أَصْحَابِهِ ضَحَايَا، فَأَعْطَانِي عَتُودًا جَذَعًا، قَالَ: فَرَجَعْتُ بِهِ إِلَيْهِ فَقُلْتُ لَهُ: إِنَّهُ جَذَعٌ، قَالَ: "ضَحِّ بِهِ". فَضَحَّيْتُ بِهِ. (د)', 'സൈദുബ്നു ഖാലിദിൽ ജുഹനീ(റ): റസൂൽ(സ) അവിടുത്തെ അനുചരർക്കിടയിൽ ബലിമൃഗങ്ങളെ വീതിച്ച് നൽകുകയും എനിക്കൊരു പ്രായം കുറഞ്ഞ ആടിനെ നൽകുകയും ചെയ്തു. നിവേദകൻ പറയുന്നു: അപ്പോൾ അതുമായി ഞാൻ അവിടുത്തെയടുക്കലേക്ക് തിരിച്ചു ചെന്ന് പറഞ്ഞു: നിശ്ചയം, ഇത് പ്രായം കുറഞ്ഞ ഒന്നാണ്. അവിടുന്ന് പറഞ്ഞു: "അതിനെ നീ ഉള്ഹിയ്യത്തറക്കുക." അപ്പോൾ ഞാനതിനെ ഉള്ഹിയ്യത്തറുത്തു. (ദ)', 'زَيْدِ بْنِ خَالِدٍ الْجُهَنِيِّ', 'സൈദുബ്നു ഖാലിദിൽ ജുഹനീ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 895, 895, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=4 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 30, 'عَنْ عُقْبَةَ بْنِ عَامِرٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَسَمَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بَيْنَ أَصْحَابِهِ أَضَاحِيَ، فَأَصَابَنِي جَذَعَةٌ، فَقُلْتُ: يَا رَسُولَ اللهِ، أَصَابَتْنِي جَذَعَةٌ؟ فَقَالَ: "ضَحِّ بِهَا". (م,ن)', 'ഉഖ്ബതുബ്നു ആമിർ(റ): റസൂൽ(സ) അവിടുത്തെ അനുചരർക്കിടയിൽ ബലിമൃഗങ്ങളെ വീതിക്കുകയും എനിക്ക് പ്രായം കുറഞ്ഞ ഒന്ന് ലഭിക്കുകയും ചെയ്തു. അപ്പോൾ ഞാൻ പറഞ്ഞു: അല്ലാഹുവിന്റെ ദൂതരേ, പ്രായം കുറഞ്ഞ ഒന്നാണെനിക്ക് ലഭിച്ചിരിക്കുന്നത്. അപ്പോൾ അവിടുന്ന് പറഞ്ഞു: "അതിനെ നീ ബലിയറുക്കുക." (മു,ന)', 'عُقْبَةَ بْنِ عَامِرٍ', 'ഉഖ്ബതുബ്നു ആമിർ(റ)', null, null, array['م','ن']::text[], array['മു','ന']::text[], null, null, 895, 895, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=4 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 31, 'عَنْ عُقْبَةَ بْنِ عَامِرٍ رَضِيَ اللهُ عَنْهُ قَالَ: ضَحَّيْنَا مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِجَذَعٍ مِنَ الضَّأْنِ. (ن)', 'ഉഖ്ബതുബ്നു ആമിർ(റ): ഞങ്ങൾ റസൂൽ(സ)യോടൊന്നിച്ച് പ്രായം കുറഞ്ഞ ഒരു ചെമ്മരിയാടിനെ ഉള്ഹിയ്യത്തറുത്തു. (ന)', 'عُقْبَةَ بْنِ عَامِرٍ', 'ഉഖ്ബതുബ്നു ആമിർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 895, 895, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=4 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 32, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "نِعْمَ - أَوْ: نِعْمَتِ - الْأُضْحِيَّةُ الْجَذَعُ مِنَ الضَّأْنِ". (ت)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറയുന്നതായി ഞാൻ കേട്ടു: "പ്രായം കുറഞ്ഞ ചെമ്മരിയാട് ഉള്ഹിയ്യത്തറുക്കപ്പെടാൻ വളരെ ഉത്തമമാണ്." (തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 896, 896, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=4 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 33, 'عَنْ عُقْبَةَ بْنِ عَامِرٍ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَعْطَاهُ غَنَمًا يَقْسِمُهَا عَلَى أَصْحَابِهِ ضَحَايَا، فَبَقِيَ عَتُودٌ أَوْ جَدْيٌ، فَذَكَرْتُ ذَلِكَ لِرَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: "ضَحِّ بِهِ أَنْتَ". (ق,ت,ن,جه)', 'ഉഖ്ബതുബ്നു ആമിർ(റ): റസൂൽ(സ) അദ്ദേഹത്തിന് അവിടുത്തെ അനുചരർക്കിടയിൽ ബലിമൃഗങ്ങളെ വീതിക്കാനായി കുറച്ച് ആടുകളെ നൽകി. അങ്ങനെ പ്രായം കുറഞ്ഞ ഒരാട്, അല്ലെങ്കിൽ: ഒരു വയസ്സിനടിയിലുള്ള ഒരാട്, ബാക്കിയായി. അപ്പോൾ ഞാനത് റസൂൽ(സ)യോട് പറഞ്ഞു. അവിടുന്ന് പറഞ്ഞു: "അതിനെ നീ ഉള്ഹിയ്യത്തറുക്കുക." (ബു,മു,തു,ന,ജ)', 'عُقْبَةَ بْنِ عَامِرٍ', 'ഉഖ്ബതുബ്നു ആമിർ(റ)', null, null, array['ق','ت','ن','جه']::text[], array['ബു','മു','തു','ന','ജ']::text[], null, null, 896, 896, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=4 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 34, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يُضَحِّي بِكَبْشَيْنِ. قَالَ أَنَسٌ: وَأَنَا أُضَحِّي بِكَبْشَيْنِ. (ن)', 'അനസ്(റ): നിശ്ചയം, റസൂൽ(സ) രണ്ട് കൊറ്റനാടുകളെ ഉള്ഹിയ്യത്തറുക്കുമായിരുന്നു. അനസ്(റ) പറയുന്നു: ഞാനും രണ്ട് കൊറ്റനാടുകളെ ഉള്ഹിയ്യത്തറുക്കുന്നു. (ന)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 896, 896, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=4 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 35, 'عَنْ أَبِي أُمَامَةَ الْبَاهِلِيِّ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "خَيْرُ الْكَفَنِ الْحُلَّةُ، وَخَيْرُ الضَّحَايَا الْكَبْشُ الْأَقْرَنُ". (ت,جه)', 'അബൂ ഉമാമതൽ ബാഹിലീ(റ): നിശ്ചയം, റസൂൽ(സ) പറഞ്ഞു: "ഏറ്റവും നല്ല കഫൻ തുണി ശരീരം മുഴുവൻ മറയുന്ന വസ്ത്രവും, ഏറ്റവും നല്ല ബലിമൃഗം കൊമ്പുള്ള കൊറ്റനാടുമാണ്." (തു,ജ)', 'أَبِي أُمَامَةَ الْبَاهِلِيِّ', 'അബൂ ഉമാമതൽ ബാഹിലീ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 896, 896, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=4 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 36, 'عَنْ أَبِي بَكْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: ثُمَّ انْصَرَفَ - كَأَنَّهُ يَعْنِي النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ - يَوْمَ النَّحْرِ إِلَى كَبْشَيْنِ أَمْلَحَيْنِ فَذَبَحَهُمَا، وَإِلَى جُذَيْعَةٍ مِنَ الْغَنَمِ فَقَسَمَهَا بَيْنَنَا. (ن)', 'അബൂബക്റഃ(റ): പിന്നെ അറവുദിവസം കറുപ്പും വെളുപ്പും നിറങ്ങൾ കലർന്ന രണ്ട് കൊറ്റനാടുകളിലേക്ക് തിരിഞ്ഞ് അവയെ അറുത്തു - നിവേദകൻ നബി(സ)യെ ഉദ്ദേശിക്കുന്നതു പോലെയുണ്ട് -. അവിടുന്ന് പ്രായം കുറഞ്ഞ ഒരുപറ്റം ആടുകളിലേക്ക് തിരിഞ്ഞ് അവയെ ഞങ്ങൾക്കിടയിൽ വീതിച്ചു. (ന)', 'أَبِي بَكْرَةَ', 'അബൂബക്റഃ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 896, 896, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=4 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 37, 'عَنْ عَلِيٍّ رَضِيَ اللهُ عَنْهُ قَالَ: نَهَى رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنْ يُضَحَّى بِمُقَابَلَةٍ أَوْ مُدَابَرَةٍ أَوْ شَرْقَاءَ أَوْ خَرْقَاءَ أَوْ جَدْعَاءَ. (د,ت,ن,جه)', 'അലി(റ): ചെവിയുടെ മുൻഭാഗമോ പിൻഭാഗമോ ഒടിഞ്ഞു തൂങ്ങിയത്, ചെവി മുറിഞ്ഞു . പോയത്, ചെവിയിൽ കീറലുള്ളത്, ചുണ്ടോ മൂക്കോ ചെവിയോ മുറിഞ്ഞത് എന്നിവയെ ഉള്ഹിയ്യത്തറുക്കൽ നബി(സ) വിലക്കിയിരിക്കുന്നു. (ദ,തു,ന,ജ)', 'عَلِيٍّ', 'അലി(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 896, 896, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=4 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 38, 'عَنْ عُبَيْدِ بْنِ فَيْرُوزَ قَالَ: قُلْتُ لِلْبَرَاءِ بْنِ عَازِبٍ رَضِيَ اللهُ عَنْهُمَا: حَدِّثْنِي بِمَا كَرِهَ - أَوْ: نَهَى عَنْهُ - رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مِنَ الْأَضَاحِيِّ. فَقَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ هَكَذَا بِيَدِهِ، وَيَدِي أَقْصَرُ مِنْ يَدِهِ: "أَرْبَعٌ لَا تُجْزِئُ فِي الْأَضَاحِي: الْعَوْرَاءُ الْبَيِّنُ عَوَرُهَا، وَالْمَرِيضَةُ الْبَيِّنُ مَرَضُهَا، وَالْعَرْجَاءُ الْبَيِّنُ ظَلْعُهَا، وَالْكَسِيرَةُ الَّتِي لَا تُنْقِي". قَالَ: فَإِنِّي أَكْرَهُ أَنْ يَكُونَ نَقْصٌ فِي الْأُذُنِ. قَالَ: فَمَا كَرِهْتَ مِنْهُ فَدَعْهُ، وَلَا تُحَرِّمْهُ عَلَى أَحَدٍ. (د,ت,ن,جه)', 'ഉബൈദുബ്നു ഫൈറൂസ്(റ): ബർറാഉബ്നു ആസിബ്(റ)വിനോട് ഞാൻ പറഞ്ഞു: ബലിമൃഗങ്ങളിൽ നബി(സ) വെറുക്കുകയോ നിരോധിക്കുകയോ ചെയ്തവയെപ്പറ്റി എനിക്ക് പറഞ്ഞുതന്നാലും. അപ്പോളദ്ദേഹം പറഞ്ഞു: റസൂൽ(സ) അവിടുത്തെ കൈകൊണ്ട് (ആംഗ്യം) ഇപ്രകാരം പറഞ്ഞു - എന്റെ കൈ അവിടുത്തെ കയ്യിനേക്കാൾ ചെറുതാണ് - "നാലെണ്ണം ഉള്ഹിയ്യത്തിന് പറ്റുകയില്ല: ഒരു കണ്ണിന് വ്യക്തമായ അന്ധതയുള്ള ഒറ്റക്കണ്ണുള്ളത്, വ്യക്തമായ രോഗമുള്ളത്, വ്യക്തമായ മുടന്തുള്ളത്, കാലൊടിഞ്ഞ് എല്ലുകളിൽ മജ്ജയില്ലാത്തത്." നിവേദകൻ പറഞ്ഞു: എങ്കിൽ മൃഗത്തിന്റെ ചെവിയിലെന്തെങ്കിലും ന്യൂനതകളുണ്ടാവുന്നത് ഞാൻ വെറുക്കുന്നു. ബർറാഅ്(റ) പറഞ്ഞു: ഞാൻ വെറുക്കുന്നതിനെ നീ ഒഴിവാക്കുക, മറ്റൊരാൾക്കും നീയത് ഹറാമാക്കരുത്. (ദ,തു,ന,ജ)', 'عُبَيْدِ بْنِ فَيْرُوزَ قَالَ', 'ഉബൈദുബ്നു ഫൈറൂസ്(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 897, 897, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=4 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 39, 'عَنْ عَلِيٍّ رَضِيَ اللهُ عَنْهُ قَالَ: الْبَقَرَةُ عَنْ سَبْعَةٍ. قُلْتُ: فَإِنْ وَلَدَتْ؟ قَالَ: اذْبَحْ وَلَدَهَا مَعَهَا. قُلْتُ: فَالْعَرْجَاءُ؟ قَالَ: إِذَا بَلَغَتِ الْمَنْسَكَ. قُلْتُ: فَمَكْسُورَةُ الْقَرْنِ؟ قَالَ: لَا بَأْسَ، أُمِرْنَا - أَوْ أَمَرَنَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ - أَنْ نَسْتَشْرِفَ الْعَيْنَيْنِ وَالْأُذُنَيْنِ. (د,ت,جه)', 'അലി(റ) പറഞ്ഞു: പശു ഏഴുപേർക്കാണ്. ഞാൻ ചോദിച്ചു: അത് പ്രസവിച്ചാലോ? അദ്ദേഹം പറഞ്ഞു: അതിന്റെ കുട്ടിയെ അതിനോടൊപ്പം നീ അറുക്കുക. ഞാൻ ചോദിച്ചു: മുടന്തുള്ളതോ? അദ്ദേഹം പറഞ്ഞു: ബലിയറുക്കുന്ന സ്ഥലത്തേക്ക് അതെത്തിയാൽ. ഞാൻ ചോദിച്ചു: കൊമ്പ് പൊട്ടിയതോ? അദ്ദേഹം പറഞ്ഞു: പ്രശ്നമൊന്നുമില്ല, ഇരു കണ്ണുകൾക്കും ചെവികൾക്കും ന്യൂനതകളുണ്ടോ എന്ന് പരിശോധിക്കാനാണ് ഞങ്ങൾ കൽപിക്കപ്പെട്ടിരിക്കുന്നത്. - അല്ലെങ്കിൽ, റസൂൽ(സ) ഞങ്ങളോട് കൽപിച്ചിരിക്കുന്നത്. (ദ,തു,ജ)', 'عَلِيٍّ', 'അലി(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 897, 897, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=4 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 40, 'عَنْ عَلِيٍّ رَضِيَ اللهُ عَنْهُ قَالَ: نَهَى رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنْ يُضَحَّى بِأَعْضَبِ الْقَرْنِ وَالْأُذُنِ. (د,ت,ن,جه)', 'അലി(റ) പറയുന്നു: നിശ്ചയം, കൊമ്പുകളോ ചെവികളോ പൊട്ടിയവയെ ബലിയറുക്കൽ റസൂൽ(സ) നിരോധിച്ചിരിക്കുന്നു. (ദ,തു,ന,ജ)', 'عَلِيٍّ', 'അലി(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 897, 897, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=4 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 41, 'عَنْ قَتَادَةَ قَالَ: قُلْتُ لِسَعِيدِ بْنِ الْمُسَيِّبِ: مَا الْأَعْضَبُ؟ قَالَ: النِّصْفُ فَمَا فَوْقَهُ. (د)', 'ഖതാദ(റ): (ചെവിയോ കൊമ്പോ) പൊട്ടിയതെന്നാൽ എന്താണർത്ഥമാക്കുന്നതെന്ന് സഇൗദുബ്നുൽ മുസയ്യിബ്(റ) വിനോട് ഞാൻ ചോദിച്ചു. അദ്ദേഹം പറഞ്ഞു: പകുതിയോ അതിൽ കൂടുതലോ (പൊട്ടിയത്). (ദ)', 'قَتَادَةَ قَالَ', 'ഖതാദ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 897, 897, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=4 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 42, 'عَنْ يَزِيدَ ذُو مِصْرٍ قَالَ: أَتَيْتُ عُتْبَةَ بْنَ عَبْدٍ السُّلَمِيَّ فَقُلْتُ: يَا أَبَا الْوَلِيدِ، إِنِّي خَرَجْتُ أَلْتَمِسُ الضَّحَايَا، فَلَمْ أَجِدْ شَيْئًا يُعْجِبُنِي غَيْرَ ثَرْمَاءَ، فَكَرِهْتُهَا، فَمَا تَقُولُ؟ قَالَ: أَفَلَا جِئْتَنِي بِهَا؟ قُلْتُ: سُبْحَانَ اللهِ! تَجُوزُ عَنْكَ وَلَا تَجُوزُ عَنِّي؟ قَالَ: نَعَمْ، إِنَّكَ تَشُكُّ وَلَا أَشُكُّ، إِنَّمَا نَهَى رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَنِ الْمُصْفَرَّةِ وَالْمُسْتَأْصَلَةِ وَالْبَخْقَاءِ وَالْمُشَيَّعَةِ وَالْكَسْرَاءِ. وَالْمُصْفَرَّةُ: الَّتِي تُسْتَأْصَلُ أُذُنُهَا حَتَّى يَبْدُوَ سِمَاخُهَا، وَالْمُسْتَأْصَلَةُ: الَّتِي اسْتُؤْصِلَ قَرْنُهَا مِنْ أَصْلِهِ، وَالْبَخْقَاءُ: الَّتِي تُبْخَقُ عَيْنُهَا، وَالْمُشَيَّعَةُ: الَّتِي لَا تَتْبَعُ الْغَنَمَ عَجَفًا وَضَعْفًا، وَالْكَسْرَاءُ: الْكَسِيرَةُ. (د)', 'യസീദു ദൂമിസ്ർ(റ): ഉത്ബതുബ്നു അബ്ദിസ്സുലമി(റ)യുടെ അടുക്കൽ ചെന്ന് ഞാനിപ്രകാരം പറഞ്ഞു: ഓ അബ്ദുൽ വലീദ്, നിശ്ചയം, ബലിമൃഗങ്ങളെയന്വേഷിച്ചാണ് ഞാനിറങ്ങിയിരിക്കുന്നത്, പക്ഷെ, മുൻപല്ലുകൾ കൊഴിഞ്ഞുപോയ ഒരു മൃഗമല്ലാതെ, എനിക്ക് ഇഷ്ടപ്പെട്ട ഒന്നിനെയും ഞാൻ കണ്ടെത്തിയില്ല. അതിനെ ഞാൻ വെറുക്കുകയും ചെയ്തു. അതിനാൽ താങ്കൾക്കെന്താണ് പറയാനുള്ളത്? അദ്ദേഹം പറഞ്ഞു: നിങ്ങൾക്കതിനെ എനിക്കുവേണ്ടി കൊണ്ടുവരാമായിരുന്നില്ലേ? ഞാൻ ചോദിച്ചു: സുബ്ഹാനല്ലാ, അത് എനിക്ക് അനുവദനീയമാവാതിരിക്കുകയും താങ്കൾക്ക് അനുവദനീയവുമോ? അദ്ദേഹം പറഞ്ഞു: അതെ, നിശ്ചയം നിങ്ങൾ സംശയിക്കുന്നു, ഞാൻ സംശയിക്കുന്നുമില്ല. നിശ്ചയം, റസൂൽ(സ) വിലക്കിയിരിക്കുന്നത് ചെവിയുടെ ദ്വാരം വെളിവാകുന്ന രൂപത്തിൽ ചെവി പറിഞ്ഞുപോയത്, കൊമ്പ് മുരടോടെ പറിഞ്ഞുപോയത്, കണ്ണ് പൊട്ടിയത്, ബലഹീനത കാരണത്താൽ ആട്ടിൻപറ്റത്തോടൊപ്പം പോകാത്തത്, പൊട്ടലുകളുള്ളത് എന്നിവയാണ്.
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 43, 'عَنْ عَلِيٍّ رَضِيَ اللهُ عَنْهُ قَالَ: أَمَرَنَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنْ نَسْتَشْرِفَ الْعَيْنَ وَالْأُذُنَ، وَأَنْ لَا نُضَحِّيَ بِعَوْرَاءَ، وَلَا مُقَابَلَةٍ وَلَا مُدَابَرَةٍ وَلَا شَرْقَاءَ وَلَا خَرْقَاءَ. (ن)', 'അലി(റ): കണ്ണിനോ ചെവിക്കോ ന്യൂനതകളുണ്ടോ എന്ന് പരിശോധിക്കാനും, ഒറ്റക്കണ്ണുള്ളത്, ചെവിയുടെ മുൻഭാഗമോ പിൻഭാഗമോ ഒടിഞ്ഞുതൂങ്ങിയത്, ചെവി മുറിഞ്ഞു പോയത്, ചെവിയിൽ കീറലുള്ളത് എന്നിവയെ ബലിയറുക്കാതിരിക്കാനും റസൂൽ(സ) ഞങ്ങളോട് കൽപിച്ചു. (ന)', 'عَلِيٍّ', 'അലി(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 898, 898, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=4 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 44, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: ابْتَعْنَا كَبْشًا نُضَحِّي بِهِ، فَأَصَابَ الذِّئْبُ مِنْ أَلْيَتِهِ أَوْ أُذُنِهِ، فَسَأَلْنَا النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَأَمَرَنَا أَنْ نُضَحِّيَ بِهِ. [ز: في إسناده متهم بالكذب] (جه)', 'അബൂസഇൗദിൽ ഖാദ്രീ(റ): ഉള്ഹിയ്യത്തറുക്കാനായി ഞങ്ങൾ ഒരു ആടിനെ വാങ്ങുകയും പിന്നീട് ഒരു ചെന്നായ അതിന്റെ പൃഷ്ടത്തിലോ ചെവിയിലോ കടിക്കുകയും ചെയ്തു. അപ്പോൾ ഞങ്ങൾ റസൂൽ(സ)യോട് ചോദിക്കുകയും അതിനെ ബലിയറുക്കാൻ അവിടുന്ന് ഞങ്ങളോട് കൽപിക്കുകയും ചെയ്തു. ഇതിന്റെ പരമ്പരയിൽ കള്ളംപറയുമെന്ന് സംശയിക്കപ്പെടുന്ന ഒരാളുണ്ട്. (ജ)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഇൗദിൽ ഖാദ്രീ(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في إسناده متهم بالكذب', null, 898, 898, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=14 where b.volume_id=4 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 45, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: كُنَّا مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي سَفَرٍ، فَحَضَرَ الْأَضْحَى، فَاشْتَرَكْنَا فِي الْبَقَرَةِ سَبْعَةً، وَفِي الْبَعِيرِ عَشَرَةً. حسن. (ت,ن,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): ഒരു യാത്രയിൽ ഞങ്ങൾ റസൂൽ(സ)യോടൊപ്പമായിരുന്നു. അപ്പോൾ ബലിദിനം സമാഗതമാകുകയും ഒരു പശുവിൽ ഏഴാളുകളും ഒരു ഒട്ടകത്തിൽ പത്താളുകളുമെന്ന നിലയിൽ ഞങ്ങൾ (അറവിൽ) പങ്കാളികളാവുകയും ചെയ്തു. (തു,ന,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ت','ن','جه']::text[], array['തു','ന','ജ']::text[], null, null, 898, 898, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=4 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 46, 'عَنْ جَابِرِ بْنِ عَبْدِ اللهِ رَضِيَ اللهُ عَنْهُمَا قَالَ: كُنَّا نَتَمَتَّعُ فِي عَهْدِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، نَذْبَحُ الْبَقَرَةَ عَنْ سَبْعَةٍ، وَالْجَزُورَ عَنْ سَبْعَةٍ، نَشْتَرِكُ فِيهَا. (م,د,ت,ن)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): പരസ്പരം പങ്കുചേർന്നുകൊണ്ട് ഏഴുപേർക്കുവേണ്ടി ഒരു പശുവിനെയും ഏഴുപേർക്കുവേണ്ടി ഒരു ആടിനെയുമറുത്ത് റസൂൽ(സ)യുടെ കാലത്ത് ഞങ്ങൾ ''തമത്ത്വുഅ്''¹ ചെയ്യാറുണ്ടായിരുന്നു. (മു,ദ,തു,ന)', 'جَابِرِ بْنِ عَبْدِ اللهِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', '¹. ഹജ്ജിന്റെ മാസങ്ങളിൽ ഹജ്ജിനും ഉംറക്കുമിടയിൽ തഹല്ലുലാവൽകൊണ്ട് വേർപിരിക്കൽ', null, array['م','د','ت','ن']::text[], array['മു','ദ','തു','ന']::text[], null, null, 899, 899, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=4 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 47, 'عَنْ جَابِرِ بْنِ عَبْدِ اللهِ رَضِيَ اللهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "الْبَقَرَةُ عَنْ سَبْعَةٍ، وَالْجَزُورُ عَنْ سَبْعَةٍ". (د,ن)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): നിശ്ചയം, നബി(സ) പറഞ്ഞു: "ഒരു പശു ഏഴുപേർക്കാണ്, ഒരു ഒട്ടകവും ഏഴുപേർക്കാണ്." (ദ,ന)', 'جَابِرِ بْنِ عَبْدِ اللهِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 899, 899, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=4 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 48, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ قَالَ: نَحَرْنَا بِالْحُدَيْبِيَةِ مَعَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: الْبَدَنَةَ عَنْ سَبْعَةٍ، وَالْبَقَرَةَ عَنْ سَبْعَةٍ. (م,د,ت,ن,جه)', 'ജാബിർ(റ): ഒരു പശു ഏഴുപേർക്കെന്ന നിലയിലും ഒരു വയസ്സുള്ള ഒരൊട്ടകം ഏഴുപേർക്കെന്ന നിലയിലും റസൂൽ(സ)യോടൊത്ത് ഹുദൈബിയ്യയിൽ വെച്ച് ഞങ്ങൾ അറുത്തു. (മു,ദ,തു,ന,ജ)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['م','د','ت','ن','جه']::text[], array['മു','ദ','തു','ന','ജ']::text[], null, null, 899, 899, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=4 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 49, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: ذَبَحَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَمَّنِ اعْتَمَرَ مِنْ نِسَائِهِ - فِي حَجَّةِ الْوَدَاعِ - بَقَرَةً بَيْنَهُنَّ. (د,جه)', 'അബൂഹുറൈറ(റ): ഹജ്ജതുൽവിദാഇൽ റസൂൽ(സ) അവിടുത്തെ ഭാര്യമാരിൽ ഉംറ നിർവഹിച്ചവർക്കുവേണ്ടി ഒരു പശുവിനെ അറുത്തു. (ദ,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 899, 899, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=4 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 50, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَلَّتِ الْإِبِلُ عَلَى عَهْدِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَأَمَرَهُمْ أَنْ يَنْحَرُوا الْبَقَرَ. (جه)', 'ഇബ്നുഅബ്ബാസ്(റ): റസൂൽ(സ)യുടെ കാലത്ത് ഒട്ടകങ്ങൾ ദുർല്ലഭമായപ്പോൾ അവിടുന്നവരോട് പശുക്കളെ അറുക്കാൻ കൽപിച്ചു. (ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 899, 899, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=4 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 51, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ نَحَرَ عَنْ آلِ مُحَمَّدٍ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ - فِي حَجَّةِ الْوَدَاعِ - بَقَرَةً وَاحِدَةً. (د,جه)', 'ആഇശ(റ): നിശ്ചയം, റസൂൽ(സ) ഹജ്ജതുൽവിദാഇൽ ആലുമുഹമ്മദിന്റെ (മുഹമ്മദ്(സ)യുടെ കുടുംബം) പേരിൽ ഒരു പശുവിനെ അറുത്തു. (ദ,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 899, 899, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=4 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 52, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَتَاهُ رَجُلٌ فَقَالَ: إِنَّ عَلَيَّ بَدَنَةً، وَأَنَا مُوسِرٌ بِهَا، وَلَا أَجِدُهَا فَأَشْتَرِيَهَا. فَأَمَرَهُ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنْ يَبْتَاعَ سَبْعَ شِيَاهٍ فَيَذْبَحَهُنَّ. [ز: في سنده ضعف] (جه)', 'ഇബ്നുഅബ്ബാസ്(റ): നിശ്ചയം, റസൂൽ(സ)യുടെ അടുക്കൽ ഒരാൾ വന്ന് ഇപ്രകാരം പറഞ്ഞു: നിശ്ചയം, ഒരൊട്ടകത്തെയറുക്കാനുള്ള ബാധ്യതയെനിക്കുണ്ട്, അതിനുള്ള കഴിവുമുണ്ടെനിക്ക്, എന്നാൽ. അതിനെ എനിക്ക് വാങ്ങാൻ കിട്ടുന്നില്ല. അപ്പോൾ റസൂൽ(സ) അദ്ദേഹത്തോട് ഏഴ് ആടുകളെ വാങ്ങി അറുക്കാൻ പറഞ്ഞു. ഇതിന്റെ പരമ്പരയിൽ ബലഹീനതയുണ്ട്. (ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في سنده ضعف', null, 899, 900, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=4 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 53, 'عَنْ رَافِعِ بْنِ خَدِيجٍ رَضِيَ اللهُ عَنْهُ قَالَ: كُنَّا مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَنَحْنُ بِذِي الْحُلَيْفَةِ مِنْ تِهَامَةَ، فَأَصَبْنَا إِبِلًا وَغَنَمًا، فَعَجِلَ الْقَوْمُ، فَأَغْلَيْنَا الْقُدُورَ قَبْلَ أَنْ تُقْسَمَ، فَأَتَانَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَأَمَرَ بِهَا فَأُكْفِئَتْ، ثُمَّ عَدَلَ الْجَزُورَ بِعَشَرَةٍ مِنَ الْغَنَمِ. (ق,د,ت,ن,جه)', 'റാഫിഉബ്നു ഖദീജ്(റ): തിഹാമയിലെ ദുൽഹുലൈഫയിൽ ഞങ്ങൾ റസൂൽ(സ)യോടൊപ്പമായിരുന്നു. അന്നേരം ഞങ്ങൾക്ക് ഒട്ടകങ്ങളും ആട്ടിൻപറ്റങ്ങളും ലഭിച്ചു. അപ്പോൾ എല്ലാവരും ധൃതികൂട്ടുകയും അവ വീതിക്കപ്പെടുന്നതിനു മുമ്പുതന്നെ ഞങ്ങൾ പാത്രങ്ങളിൽ വെള്ളം തിളപ്പിക്കുകയും ചെയ്തു. ഉടനെ റസൂൽ(സ) വരികയും അവിടുന്ന് കൽപിച്ചതു പ്രകാരം ആ പാത്രങ്ങൾ കമിഴ്ത്തപ്പെടുകയും ചെയ്തു. ശേഷം അവിടുന്ന് പത്ത് ആടുകൾക്ക് പകരമായിരിക്കും ഒരു ഒട്ടകമെന്ന് കണക്ക് നിശ്ചയിച്ചു. (ബു,മു,ദ,തു,ന,ജ)', 'رَافِعِ بْنِ خَدِيجٍ', 'റാഫിഉബ്നു ഖദീജ്(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 900, 900, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=4 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 54, 'عَنْ رَافِعِ بْنِ خَدِيجٍ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَجْعَلُ فِي قَسْمِ الْغَنَائِمِ عَشْرًا مِنَ الشَّاءِ بِبَعِيرٍ. (ن)', 'റാഫിഉബ്നു ഖദീജ്(റ): റസൂൽ(സ) യുദ്ധമുതൽ വീതിക്കുമ്പോൾ ഒരൊട്ടകത്തിന് പകരം പത്ത് ആടുകളെ നിശ്ചയിച്ചിരുന്നു. (ന)', 'رَافِعِ بْنِ خَدِيجٍ', 'റാഫിഉബ്നു ഖദീജ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 900, 900, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=4 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 55, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: كُنَّا مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي سَفَرٍ، فَحَضَرَ النَّحْرُ، فَاشْتَرَكْنَا فِي الْبَعِيرِ عَنْ عَشَرَةٍ، وَالْبَقَرَةِ عَنْ سَبْعَةٍ. (ن)', 'ഇബ്നുഅബ്ബാസ്(റ): ഞങ്ങൾ റസൂൽ(സ)യോടൊപ്പം ഒരു യാത്രയിലായിരിക്കെ അറവു ദിവസം സമാഗതമാവുകയും ഒരൊട്ടകത്തിന് പത്ത് പേരും ഒരു പശുവിന് ഏഴ് പേരുമെന്ന നിലയിൽ ഞങ്ങൾ പരസ്പരം (അറവിൽ) പങ്കാളികളാവുകയും ചെയ്തു. (ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 900, 900, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=4 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 56, 'عَنْ كُلَيْبِ بْنِ شِهَابٍ قَالَ: كُنَّا فِي سَفَرٍ، فَحَضَرَ الْأَضْحَى، فَجَعَلَ الرَّجُلُ مِنَّا يَشْتَرِي الْمُسِنَّةَ بِالْجَذَعَتَيْنِ وَالثَّلَاثَةِ، فَقَالَ لَنَا رَجُلٌ مِنْ مُزَيْنَةَ: كُنَّا مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي سَفَرٍ، فَحَضَرَ هَذَا الْيَوْمُ، فَجَعَلَ الرَّجُلُ يَطْلُبُ الْمُسِنَّةَ بِالْجَذَعَتَيْنِ وَالثَّلَاثَةِ، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ الْجَذَعَ يُوفِي مِمَّا يُوفِي مِنْهُ الثَّنِيُّ". وَفِي رِوَايَةٍ: يُحَدَّثُ عَنْ رَجُلٍ قَالَ: كُنَّا مَعَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَبْلَ الْأَضْحَى بِيَوْمَيْنِ، نُعْطِي الْجَذَعَتَيْنِ بِالثَّنِيَّةِ، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ الْجَذَعَةَ تُجْزِئُ مَا تُجْزِئُ مِنْهُ الثَّنِيَّةُ". (ن)', 'കുലൈബുബ്നു ശിഹാബ്(റ): ഞങ്ങളൊരു യാത്രയിലായിരിക്കെ ബലിദിനം സമാഗതമായി. അപ്പോൾ ഞങ്ങളിൽപ്പെട്ട ഒരാൾ പ്രായം കുറഞ്ഞ രണ്ടോ മൂന്നോ മൃഗങ്ങൾക്കു പകരമായി പല്ലുകൾ മുളച്ച് വലുതായ ഒരു മൃഗത്തെ വാങ്ങാൻ തുടങ്ങി. അപ്പോൾ മുസൈന ഗോത്രത്തിൽ പെട്ട ഒരാൾ ഞങ്ങളോട് പറഞ്ഞു: ഒരു യാത്രയിൽ ഞങ്ങൾ റസൂൽ(സ)യോടൊപ്പമായിരുന്നു, അപ്പോൾ ഈ ദിവസം സമാഗതമാകുകയും ഒരാൾ പ്രായം കുറഞ്ഞ രണ്ടോ മൂന്നോ മൃഗങ്ങൾക്കു പകരമായി പല്ലുകൾ മുളച്ച് വലുതായ ഒരു മൃഗത്തെ അന്വേഷിക്കാൻ തുടങ്ങുകയും ചെയ്തു. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "പല്ല് മുളച്ച് വലുതായ മൃഗം മതിയാവുന്നിടത്തെല്ലാം പ്രായം കുറഞ്ഞ മൃഗവും മതിയാവുന്നതാണ്."
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=4 and b.book_no=17 and h.hadith_no=56), 1, 'وَفِي رِوَايَةٍ: يُحَدَّثُ عَنْ رَجُلٍ قَالَ: كُنَّا مَعَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَبْلَ الْأَضْحَى بِيَوْمَيْنِ، نُعْطِي الْجَذَعَتَيْنِ بِالثَّنِيَّةِ، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ الْجَذَعَةَ تُجْزِئُ مَا تُجْزِئُ مِنْهُ الثَّنِيَّةُ". (ن)', 'മറ്റൊരു നിവേദനത്തിൽ ഒരാളെക്കുറിച്ച് ഹദീസ് പറയുന്നു: ഒരു ബലിദിനത്തിന്റെ രണ്ടു ദിവസം മുമ്പ് ഞങ്ങൾ റസൂൽ(സ)യോടൊപ്പമായിരുന്നു. പല്ലുകൾ മുളച്ച് വലുതായ ഒരു മൃഗത്തിന് പകരമായി പ്രായം കുറഞ്ഞ രണ്ട് മൃഗങ്ങളെ ഞങ്ങൾ നൽകുമായിരുന്നു. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "പല്ല് മുളച്ച് വലുതായ മൃഗം പകരം നിൽക്കുന്നതിനെല്ലാം പ്രായം കുറഞ്ഞ മൃഗവും പകരം നിൽക്കും." (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 57, 'عَنْ عَطَاءِ بْنِ يَسَارٍ قَالَ: سَأَلْتُ أَبَا أَيُّوبَ الْأَنْصَارِيَّ رَضِيَ اللهُ عَنْهُ: كَيْفَ كَانَتِ الضَّحَايَا فِيكُمْ عَلَى عَهْدِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ؟ قَالَ: كَانَ الرَّجُلُ فِي عَهْدِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُضَحِّي بِالشَّاةِ عَنْهُ وَعَنْ أَهْلِ بَيْتِهِ، فَيَأْكُلُونَ وَيُطْعِمُونَ، ثُمَّ تَبَاهَى النَّاسُ، فَصَارَ كَمَا تَرَى. (ت,جه)', 'അത്വാഉബ്നു യസാർ(റ): റസൂൽ(സ)യുടെ കാലത്ത് നിങ്ങളിലെ ഉള്ഹിയ്യത്ത് എങ്ങനെയായിരുന്നുവെന്ന് അബൂഅയ്യൂബിൽ അൻസ്വാരി(റ)വിനോട് ഞാൻ ചോദിച്ചു. അദ്ദേഹം പറഞ്ഞു: റസൂൽ(സ)യുടെ കാലത്ത് ഒരാൾ തന്റെയും തന്റെ കുടുംബത്തിന്റെയും പേരിൽ ഒരാടിനെ ഉള്ഹിയ്യത്തറുക്കുകയും അതിനെ ഭക്ഷിക്കുകയും ഭക്ഷിപ്പിക്കുകയും ചെയ്തിരുന്നു, പിന്നീട് ജനങ്ങൾ പരസ്പരം അഭിമാനം നടിക്കുകയും നിങ്ങളീ കാണുന്നതുപോലെയെല്ലാം ആയിത്തീരുകയും ചെയ്തു. (തു,ജ)', 'عَطَاءِ بْنِ يَسَارٍ قَالَ', 'അത്വാഉബ്നു യസാർ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 901, 901, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=4 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 58, 'عَنْ أَبِي سَرِيحَةَ حُذَيْفَةَ بْنِ أَسِيدٍ رَضِيَ اللهُ عَنْهُ قَالَ: حَمَلَنِي أَهْلِي عَلَى الْجَفَاءِ، بَعْدَ مَا عَلِمْتُ مِنَ السُّنَّةِ، كَانَ أَهْلُ الْبَيْتِ يُضَحُّونَ بِالشَّاةِ وَالشَّاتَيْنِ، وَالْآنَ يُبَخِّلُنَا جِيرَانُنَا. (جه)', 'അബൂസരീഹ ഹുദൈഫതുബ്നു ഉസൈദ്(റ): തിരുചര്യ ഞാൻ മനസ്സിലാക്കിയതിനു ശേഷം എന്റെ കുടുംബം നാടുവിടാൻ എന്നെ പ്രേരിപ്പിക്കുകയാണ്. ഒരു കുടുംബം ഒന്നോ രണ്ടോ ആടുകളെയാണ് ഉള്ഹിയ്യത്തറുത്തിരുന്നത്. എന്നാൽ എന്റെ അയൽവാസികളിപ്പോൾ ഞാനൊരു പിശുക്കനാണെന്നാണ് പറയുന്നത്. (ജ)', 'أَبِي سَرِيحَةَ حُذَيْفَةَ بْنِ أَسِيدٍ', 'അബൂസരീഹ ഹുദൈഫതുബ്നു ഉസൈദ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 901, 901, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=4 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 59, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا، وَقَدْ سُئِلَتْ: أَكَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَنْهَى عَنْ لُحُومِ الْأَضَاحِيِّ بَعْدَ ثَلَاثٍ؟ قَالَتْ: نَعَمْ، أَصَابَ النَّاسَ شِدَّةٌ، فَأَحَبَّ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنْ يُطْعِمَ الْغَنِيُّ الْفَقِيرَ، ثُمَّ قَالَتْ: لَقَدْ رَأَيْتُ آلَ مُحَمَّدٍ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَأْكُلُونَ الْكُرَاعَ بَعْدَ خَمْسَ عَشْرَةَ، قِيلَ: مِمَّ ذَاكَ؟ فَضَحِكَتْ، فَقَالَتْ: مَا شَبِعَ آلُ مُحَمَّدٍ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مِنْ خُبْزٍ مَأْدُومٍ ثَلَاثَةَ أَيَّامٍ، حَتَّى لَحِقَ بِاللهِ عَزَّ وَجَلَّ. (ن)', 'ആഇശ(റ): മൂന്ന് ദിവസങ്ങൾക്കു ശേഷം ഉള്ഹിയ്യത്തിന്റെ മാംസം (ഭക്ഷിക്കുന്നത്) റസൂൽ(സ) നിരോധിക്കാറുണ്ടായിരുന്നോ എന്ന് മഹതിയോട് ചോദിക്കപ്പെട്ടു. മഹതി പറഞ്ഞു: അതെ, ജനങ്ങൾക്ക് ക്ഷാമകാലം വരികയും ധനികൻ ദരിദ്രനെ ഭക്ഷിപ്പിക്കാൻ റസൂൽ(സ) ഇഷ്ടപ്പെടുകയും ചെയ്തു. പിന്നെ മഹതി പറഞ്ഞു: നിശ്ചയം, റസൂൽ(സ)യുടെ കുടുംബം ഒരു കുറക് പതിനഞ്ചുദിവസങ്ങൾക്കു ശേഷം ഭക്ഷിക്കുന്നത് ഞാൻ കണ്ടിട്ടുണ്ട്. അപ്പോൾ ചോദിക്കപ്പെട്ടു: എന്തുകാരണത്താലാണത്? അപ്പോൾ മഹതി ചിരിക്കുകയും ഇപ്രകാരം പറയുകയും ചെയ്തു: തിരുമേനി(സ) അല്ലാഹുവുമായി ചേരുന്നതുവരെ മുഹമ്മദ്(സ)യുടെ കുടുംബം കറിയൊഴിച്ച റൊട്ടികൊണ്ട് മൂന്ന് ദിവസം വയറ് നിറച്ചിട്ടില്ല. (ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 901, 901, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=4 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 60, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كُنَّا نَخْبَأُ الْكُرَاعَ لِرَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ شَهْرًا، ثُمَّ يَأْكُلُهُ. (ن)', 'ആഇശ(റ): റസൂൽ(സ)ക്കുവേണ്ടി ഒരു മാസം കുറക് ഞങ്ങൾ ഒളിപ്പിച്ചുവെക്കാറുണ്ടായിരുന്നു. ശേഷം അവിടുന്നത് തിന്നുകയും ചെയ്യും. (ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 901, 901, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=4 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 61, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: نَهَى رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَنْ إِمْسَاكِ الْأُضْحِيَّةِ فَوْقَ ثَلَاثَةِ أَيَّامٍ، ثُمَّ قَالَ: "كُلُوا وَأَطْعِمُوا". (ن)', 'അബൂസഈദിൽ ഖുദ്രീ(റ): ഉള്ഹിയ്യത്തിന്റെ മാംസം മൂന്ന് ദിവസത്തിലേറെ സൂക്ഷിച്ചുവെക്കുന്നത് റസൂൽ(സ) വിലക്കുകയും പിന്നീട് അവിടുന്ന് ഇപ്രകാരം പറയുകയും ചെയ്തു: "നിങ്ങൾ ഭക്ഷിക്കുകയും ഭക്ഷിപ്പിക്കുകയും ചെയ്യുക." (ന)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദിൽ ഖുദ്രീ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 902, 902, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=4 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 62, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ نَهَى أَنْ تُؤْكَلَ لُحُومُ الْأَضَاحِيِّ بَعْدَ ثَلَاثٍ. (ق,ن)', 'ഇബ്നുഉമർ(റ): തീർച്ചയായും, മൂന്ന് ദിവസത്തിന് ശേഷം ഉള്ഹിയ്യത്ത് ഭക്ഷിക്കുന്നത് റസൂൽ(സ) നിരോധിച്ചിരിക്കുന്നു. (ബു,മു,ന)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ق','ن']::text[], array['ബു','മു','ന']::text[], null, null, 902, 902, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=4 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 63, 'عَنْ عَلِيِّ بْنِ أَبِي طَالِبٍ كَرَّمَ اللهُ وَجْهَهُ في يَوْم عيد: بَدَأَ بِالصَّلَاةِ قَبْلَ الْخُطْبَةِ، ثُمَّ صَلَّى بِلَا أَذَانٍ وَلَا إِقَامَةٍ، ثُمَّ قَالَ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَنْهَى أَنْ يُمْسِكَ أَحَدٌ مِنْ نُسُكِهِ شَيْئًا فَوْقَ ثَلَاثَةِ أَيَّامٍ. وَفِي رِوَايَةٍ: إِنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَدْ نَهَاكُمْ أَنْ تَأْكُلُوا لُحُومَ نُسُكِكُمْ فَوْقَ ثَلَاثٍ. (م,ن)', 'അലിയ്യുബ്നു അബീത്വാലിബ്(റ): ഒരു പെരുന്നാളിന് അദ്ദേഹം ഖുത്വുബക്ക് മുമ്പായി നിസ്കാരമാരംഭിക്കുകയും ശേഷം ബാങ്കോ ഇഖാമത്തോ ഇല്ലാതെ നിസ്കരിക്കുകയും ചെയ്തു. എന്നിട്ടദ്ദേഹം പറഞ്ഞു: ബലിയറുക്കപ്പെട്ടതിൽ നിന്ന് വല്ലതും മൂന്ന് ദിവസത്തേക്കാൾ കൂടുതൽ ഒരാൾ സൂക്ഷിച്ചുവെക്കുന്നത് റസൂൽ(സ) വിലക്കുന്നത് ഞാൻ കേട്ടു. മറ്റൊരു നിവേദനം: നിശ്ചയം, ബലിയറുക്കപ്പെട്ടവയിൽ നിന്ന് മൂന്ന് ദിവസത്തേക്കാൾ കൂടുതൽ നിങ്ങൾ വല്ലതും ഭക്ഷിക്കുന്നത് റസൂൽ(സ) നിരോധിച്ചിരിക്കുന്നു. (മു,ന)', 'عَلِيِّ بْنِ أَبِي طَالِبٍ كَرَّمَ اللهُ وَجْهَهُ في يَوْم عيد', 'അലിയ്യുബ്നു അബീത്വാലിബ്(റ)', null, null, array['م','ن']::text[], array['മു','ന']::text[], null, null, 902, 902, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=4 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=4 and b.book_no=17 and h.hadith_no=63), 1, 'وَفِي رِوَايَةٍ: إِنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَدْ نَهَاكُمْ أَنْ تَأْكُلُوا لُحُومَ نُسُكِكُمْ فَوْقَ ثَلَاثٍ. (م,ن)', 'മറ്റൊരു നിവേദനം: നിശ്ചയം, ബലിയറുക്കപ്പെട്ടവയിൽ നിന്ന് മൂന്ന് ദിവസത്തേക്കാൾ കൂടുതൽ നിങ്ങൾ വല്ലതും ഭക്ഷിക്കുന്നത് റസൂൽ(സ) നിരോധിച്ചിരിക്കുന്നു. (മു,ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 64, 'عَنْ جَابِرِ بْنِ عَبْدِ اللهِ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنْ أَكْلِ لُحُومِ الضَّحَايَا بَعْدَ ثَلَاثٍ، ثُمَّ قَالَ: "كُلُوا وَتَزَوَّدُوا وَادَّخِرُوا". (د,ن,جه)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): തീർച്ചയായും, മൂന്ന് ദിവസത്തിന് ശേഷം ഉള്ഹിയ്യത്തിന്റെ മാംസം ഭക്ഷിക്കൽ റസൂൽ(സ) നിരോധിച്ചിരിക്കുന്നു. ശേഷം അവിടുന്ന് പറഞ്ഞു: "നിങ്ങൾ ഭക്ഷിക്കുകയും പാഥേയമൊരുക്കുകയും സൂക്ഷിച്ചുവെക്കുകയും ചെയ്യുക." (ദ,ന,ജ)', 'جَابِرِ بْنِ عَبْدِ اللهِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['د','ن','جه']::text[], array['ദ','ന','ജ']::text[], null, null, 902, 902, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=4 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 65, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ: قَدِمَ مِنْ سَفَرٍ، فَقُدِّمَ إِلَيْهِ أَهْلُهُ لَحْمًا مِنْ لُحُومِ الْأَضَاحِي، فَقَالَ: مَا أَنَا بِآكِلِهِ حَتَّى أَسْأَلَ. فَانْطَلَقَ إِلَى أَخِيهِ لِأُمِّهِ قَتَادَةَ بْنِ النُّعْمَانِ – وَكَانَ بَدْرِيًّا – فَسَأَلَهُ عَنْ ذَلِكَ، فَقَالَ: إِنَّهُ قَدْ حَدَثَ بَعْدَكَ أَمْرٌ، نَقْضًا لِمَا كَانُوا نُهُوا عَنْهُ مِنْ أَكْلِ لُحُومِ الْأَضَاحِي بَعْدَ ثَلَاثَةِ أَيَّامٍ. (خ,ن)', 'അബൂസഈദിൽ ഖുദ്രി(റ): അദ്ദേഹം ഒരു യാത്ര കഴിഞ്ഞ് മടങ്ങിവന്നപ്പോൾ അദ്ദേഹത്തിന്റെ കുടുംബം ഉള്ഹിയ്യത്തിന്റെ മാംസം അദ്ദേഹത്തിന് നൽകി. അപ്പോഴദ്ദേഹം പറഞ്ഞു: അതേക്കുറിച്ച് ചോദിക്കുന്നത് വരെ ഞാനത് ഭക്ഷിക്കുന്നതല്ല. അങ്ങനെ അദ്ദേഹം തന്റെ ഉമ്മയൊത്ത സഹോദരനും ബദ്റിൽ പങ്കെടുത്തവരുമായ ഖതാദതുബ്നു നുഅ്മാൻ(റ)വിന്റെയടുക്കൽ ചെല്ലുകയും അതിനെക്കുറിച്ച് ചോദിക്കുകയും ചെയ്തു. അപ്പോഴദ്ദേഹം പറഞ്ഞു: ഉള്ഹിയ്യത്തിന്റെ മാംസം മൂന്ന് ദിവസങ്ങൾക്ക് ശേഷം ഭക്ഷിക്കുന്നത് അവർക്ക് വിലക്കപ്പെട്ടിരുന്നതിനെ തിരുത്തിക്കൊണ്ട്, നിങ്ങൾ പോയതിനുശേഷം മറ്റൊരു നിയമം ഉണ്ടായിരിക്കുന്നു. (ബു,ന)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദിൽ ഖുദ്രി(റ)', null, null, array['خ','ن']::text[], array['ബു','ന']::text[], null, null, 902, 902, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=4 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 66, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنْ لُحُومِ الْأَضَاحِي فَوْقَ ثَلَاثَةِ أَيَّامٍ، فَقَدِمَ قَتَادَةُ بْنُ النُّعْمَانِ – وَكَانَ أَخَا أَبِي سَعِيدٍ لِأُمِّهِ، وَكَانَ بَدْرِيًّا – فَقَدَّمُوا إِلَيْهِ فَقَالَ: أَلَيْسَ نَهَى عَنْهُ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ؟ قَالَ أَبُو سَعِيدٍ: إِنَّهُ قَدْ حَدَثَ فِيهِ أَمْرٌ، أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ نَهَانَا أَنْ نَأْكُلَهُ فَوْقَ ثَلَاثَةِ أَيَّامٍ، ثُمَّ رَخَّصَ لَنَا أَنْ نَأْكُلَهُ وَنَدَّخِرَهُ. (ن)', 'അബൂസഈദിൽ ഖുദ്രി(റ): മൂന്ന് ദിവസങ്ങൾക്ക് ശേഷം ഉള്ഹിയ്യത്തിന്റെ മാംസം ഭക്ഷിക്കുന്നത് റസൂൽ(സ) വിലക്കിയിരിക്കുന്നു. അപ്പോൾ അബൂസഈദ്(റ)വിന്റെ ഉമ്മയൊത്ത സഹോദരനും ബദ്റിൽ പങ്കെടുത്തവരുമായ ഖതാദതുബ്നു നുഅ്മാൻ(റ) കടന്നുവരികയും അവരദ്ദേഹത്തിന് (ഉള്ഹിയത്തിന്റെ മാംസം) നൽകുകയും ചെയ്തു. അപ്പോൾ അദ്ദേഹം ചോദിച്ചു: റസൂൽ(സ) അത് വിലക്കിയിട്ടില്ലയോ? അബൂസഈദ്(റ) പറഞ്ഞു: തീർച്ചയായും അതിൽ പുതിയൊരു കാര്യമുണ്ടായിരിക്കുന്നു. നിശ്ചയം മൂന്ന് ദിവസങ്ങൾക്കു ശേഷം അത് ഭക്ഷിക്കുന്നത് റസൂൽ(സ) നിരോധിക്കുകയും പിന്നീട് അത് ഭക്ഷിക്കാനും സൂക്ഷിച്ചുവെക്കാനും ഇളവ് നൽകുകയും ചെയ്തു. (ന)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദിൽ ഖുദ്രി(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 902, 903, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=4 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 67, 'عَنْ بُرَيْدَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنِّي كُنْتُ نَهَيْتُكُمْ عَنْ ثَلَاثٍ: عَنْ زِيَارَةِ الْقُبُورِ، فَزُورُوهَا، وَلْتَزْدْكُمْ زِيَارَتُهَا خَيْرًا. وَنَهَيْتُكُمْ عَنْ لُحُومِ الْأَضَاحِيِّ بَعْدَ ثَلَاثٍ، فَكُلُوا مِنْهَا وَأَمْسِكُوا مَا شِئْتُمْ. وَنَهَيْتُكُمْ عَنِ الْأَشْرِبَةِ فِي الْأَوْعِيَةِ، فَاشْرَبُوا فِي أَيِّ وِعَاءٍ شِئْتُمْ، وَلَا تَشْرَبُوا مُسْكِرًا". وَفِي رِوَايَةٍ: "إِنِّي كُنْتُ نَهَيْتُكُمْ عَنْ لُحُومِ الْأَضَاحِيِّ بَعْدَ ثَلَاثٍ، وَعَنِ النَّبِيذِ إِلَّا فِي سِقَاءٍ، وَعَنْ زِيَارَةِ الْقُبُورِ. فَكُلُوا مِنْ لُحُومِ الْأَضَاحِيِّ مَا بَدَا لَكُمْ وَتَزَوَّدُوا وَادَّخِرُوا، وَمَنْ أَرَادَ زِيَارَةَ الْقُبُورِ فَإِنَّهَا تُذَكِّرُ الْآخِرَةَ، وَاشْرَبُوا وَاتَّقُوا كُلَّ مُسْكِرٍ". (ن)', 'ബുറൈദ(റ): റസൂൽ(സ) പറഞ്ഞു: "നിശ്ചയം, മൂന്ന് കാര്യങ്ങൾ നിങ്ങൾക്ക് ഞാൻ നിരോധിച്ചിരുന്നു: ഖബ്ർ സിയാറത്ത്, ഇനി നിങ്ങളത് സന്ദർശിക്കുക. നിശ്ചയം ഖബ്ർ സിയാറത്ത് നിങ്ങൾക്ക് നന്മ വർധിപ്പിക്കും. മൂന്ന് ദിവസങ്ങൾക്ക് ശേഷം ഉള്ഹിയ്യത്തിന്റെ മാംസവും നിങ്ങൾക്ക് ഞാൻ നിരോധിച്ചിരുന്നു. ഇനി നിങ്ങളത് തിന്നുകയും ഉദ്ദേശിക്കുന്നയത്ര സൂക്ഷിച്ചുവെക്കുകയും ചെയ്യുക. പാത്രങ്ങളിലുള്ള പാനീയങ്ങളും നിങ്ങൾക്ക് ഞാൻ വിലക്കിയിരുന്നു. ഇനി നിങ്ങളുദ്ദേശിക്കുന്ന ഏത് പാത്രത്തിലും നിങ്ങൾ കുടിക്കുക. മത്തുണ്ടാക്കുന്ന യാതൊന്നും നിങ്ങൾ കുടിക്കുകയുമരുത്." മറ്റൊരു നിവേദനം: "മൂന്ന് ദിവസങ്ങൾക്ക് ശേഷം ഉള്ഹിയ്യത്തിന്റെ മാംസം ഭക്ഷിക്കലും, തോൽപാത്രത്തിലല്ലാത്ത മുന്തിരിച്ചാറും, ഖബ്ർ സിയാറത്തും നിങ്ങൾക്ക് ഞാൻ നിരോധിച്ചിരുന്നു. ഇനി നിങ്ങൾ ഉള്ഹിയ്യത്തിന്റെ മാംസം തോന്നുന്നയത്ര ഭക്ഷിക്കുകയും പാഥേയമൊരുക്കുകയും സൂക്ഷിച്ചുവെക്കുകയും ചെയ്യുക. ആരെങ്കിലും ഖബ്ർ സന്ദർശനം ഉദ്ദേശിക്കുന്നുവെങ്കിൽ നിശ്ചയമത് പരലോകത്തെ ഓർമിപ്പിക്കും. നിങ്ങൾ കുടിക്കുകയും മത്തുണ്ടാക്കുന്ന സകലതിനെയും സൂക്ഷിക്കുകയും ചെയ്യുക." (ന)', 'بُرَيْدَةَ', 'ബുറൈദ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 903, 903, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=4 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=4 and b.book_no=17 and h.hadith_no=67), 1, 'وَفِي رِوَايَةٍ: "إِنِّي كُنْتُ نَهَيْتُكُمْ عَنْ لُحُومِ الْأَضَاحِيِّ بَعْدَ ثَلَاثٍ، وَعَنِ النَّبِيذِ إِلَّا فِي سِقَاءٍ، وَعَنْ زِيَارَةِ الْقُبُورِ. فَكُلُوا مِنْ لُحُومِ الْأَضَاحِيِّ مَا بَدَا لَكُمْ وَتَزَوَّدُوا وَادَّخِرُوا، وَمَنْ أَرَادَ زِيَارَةَ الْقُبُورِ فَإِنَّهَا تُذَكِّرُ الْآخِرَةَ، وَاشْرَبُوا وَاتَّقُوا كُلَّ مُسْكِرٍ". (ن)', 'മറ്റൊരു നിവേദനം: "മൂന്ന് ദിവസങ്ങൾക്ക് ശേഷം ഉള്ഹിയ്യത്തിന്റെ മാംസം ഭക്ഷിക്കലും, തോൽപാത്രത്തിലല്ലാത്ത മുന്തിരിച്ചാറും, ഖബ്ർ സിയാറത്തും നിങ്ങൾക്ക് ഞാൻ നിരോധിച്ചിരുന്നു. ഇനി നിങ്ങൾ ഉള്ഹിയ്യത്തിന്റെ മാംസം തോന്നുന്നയത്ര ഭക്ഷിക്കുകയും പാഥേയമൊരുക്കുകയും സൂക്ഷിച്ചുവെക്കുകയും ചെയ്യുക. ആരെങ്കിലും ഖബ്ർ സന്ദർശനം ഉദ്ദേശിക്കുന്നുവെങ്കിൽ നിശ്ചയമത് പരലോകത്തെ ഓർമിപ്പിക്കും. നിങ്ങൾ കുടിക്കുകയും മത്തുണ്ടാക്കുന്ന സകലതിനെയും സൂക്ഷിക്കുകയും ചെയ്യുക." (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 68, 'عَنْ عَبْدِ اللهِ بْنِ أَبِي بَكْرٍ، عَنْ عَبْدِ اللهِ بْنِ وَاقِدٍ رَضِيَ اللهُ عَنْهُ قَالَ: نَهَى رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَنْ أَكْلِ لُحُومِ الضَّحَايَا بَعْدَ ثَلَاثٍ. قَالَ عَبْدُ اللهِ بْنُ أَبِي بَكْرٍ: فَذَكَرْتُ ذَلِكَ لِعَمْرَةَ، فَقَالَتْ: صَدَقَ، سَمِعْتُ عَائِشَةَ رَضِيَ اللهُ عَنْهَا تَقُولُ: دَفَّ أَهْلُ أَبْيَاتٍ مِنْ أَهْلِ الْبَادِيَةِ حَضْرَةَ الْأَضْحَى، زَمَنَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "ادَّخِرُوا ثَلَاثًا، ثُمَّ تَصَدَّقُوا بِمَا بَقِيَ". فَلَمَّا كَانَ بَعْدَ ذَلِكَ قَالُوا: يَا رَسُولَ اللهِ، إِنَّ النَّاسَ يَتَّخِذُونَ الْأَسْقِيَةَ مِنْ ضَحَايَاهُمْ، وَيَجْمُلُونَ مِنْهَا الْوَدَكَ. فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "وَمَا ذَاكَ". قَالُوا: نَهَيْتَ أَنْ تُؤْكَلَ لُحُومُ الضَّحَايَا بَعْدَ ثَلَاثٍ، فَقَالَ: "إِنَّمَا نَهَيْتُكُمْ مِنْ أَجْلِ الدَّافَّةِ الَّتِي دَفَّتْ، فَكُلُوا وَادَّخِرُوا وَتَصَدَّقُوا". (م,د,ن)', 'അബ്ദുല്ലാഹിബ്നു വാഖിദ്(റ)വിൽനിന്ന് അബ്ദുല്ലാഹിബ്നു അബൂബകർ(റ): ഉള്ഹിയ്യത്തിന്റെ മാംസം മൂന്ന് ദിവസങ്ങൾക്ക് ശേഷം ഭക്ഷിക്കൽ റസൂൽ(സ) നിരോധിച്ചിരിക്കുന്നു. അബ്ദുല്ലാഹിബ്നു അബീബക്ർ(റ) പറയുന്നു: ഇക്കാര്യം ഞാൻ അംറഃ(റ)യോട് പറഞ്ഞു: അപ്പോൾ മഹതി പറഞ്ഞു: അദ്ദേഹം സത്യമാണ് പറഞ്ഞിരിക്കുന്നത്. ആഇശ(റ) പറയുന്നതായി ഞങ്ങൾ കേട്ടിരിക്കുന്നു: റസൂൽ(സ)യുടെ കാലത്ത് ഒരു ബലിപെരുന്നാൾ സമാഗതമായപ്പോൾ നാട്ടിൻപുറത്ത് താമസിക്കുന്ന ചില കുടുംബങ്ങൾ വന്നു. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങൾ മൂന്ന് ദിവസം സൂക്ഷിച്ചുവെക്കുകയും ശേഷം ബാക്കിവന്നത് ദാനംചെയ്യുകയും ചെയ്യുക." അടുത്ത കൊല്ലമായപ്പോൾ അവർ പറഞ്ഞു: അല്ലാഹുവിന്റെ ദൂതരേ, തീർച്ചയായും ജനങ്ങൾ അവരുടെ ബലിമൃഗങ്ങളിൽ നിന്ന് തോൽപാത്രങ്ങളുണ്ടാക്കുകയും അതിൽനിന്ന് നെയ്യ് ഉരുക്കി സൂക്ഷിക്കുന്നുമുണ്ട്. അപ്പോൾ റസൂൽ(സ) ചോദിച്ചു: "അതിനെന്താ കുഴപ്പം?" അവർ പറഞ്ഞു: മൂന്ന് ദിവസങ്ങൾക്ക് ശേഷം ഉള്ഹിയ്യത്തിന്റെ മാംസം ഭക്ഷിക്കൽ അങ്ങ് വിലക്കിയിരുന്നു. അപ്പോൾ അവിടുന്ന് പറഞ്ഞു: "നിശ്ചയം, നിങ്ങൾക്ക് ഞാനത് നിരോധിച്ചിരുന്നത് അന്ന് തടിച്ചുകൂടിയവർ കാരണത്താലായിരുന്നു. അതിനാൽ നിങ്ങൽ ഭക്ഷിക്കുകയും സൂക്ഷിച്ചുവെക്കുകയും ദാനം ചെയ്യുകയും ചെയ്യുക." (മു,ദ,ന)', 'عَبْدِ اللهِ بْنِ أَبِي بَكْرٍ، عَنْ عَبْدِ اللهِ بْنِ وَاقِدٍ', 'അബ്ദുല്ലാഹിബ്നു വാഖിദ്(റ)', null, null, array['م','د','ن']::text[], array['മു','ദ','ന']::text[], null, null, 903, 904, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=4 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 69, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: إِنَّمَا نَهَى رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَنْ لُحُومِ الْأَضَاحِيِّ لِجَهْدِ النَّاسِ، ثُمَّ رَخَّصَ فِيهَا. (ق,ت,ن,جه)', 'ആഇശ(റ): നിശ്ചയം, റസൂൽ(സ) ഉള്ഹിയ്യത്തിന്റെ മാംസം വിലക്കിയത് ജനങ്ങൾക്കനുഭവപ്പെട്ട ക്ഷാമം കാരണമാണ്. പിന്നീടതിൽ ഇളവ് വരുത്തി. (ബു,മു,തു,ന,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ق','ت','ن','جه']::text[], array['ബു','മു','തു','ന','ജ']::text[], null, null, 904, 904, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=4 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 70, 'عَنْ نُبَيْشَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنَّا كُنَّا نَهَيْنَاكُمْ عَنْ لُحُومِهَا أَنْ تَأْكُلُوهَا فَوْقَ ثَلَاثٍ لِكَيْ تَسَعَكُمْ، فَقَدْ جَاءَ اللهُ بِالسَّعَةِ، فَكُلُوا وَادَّخِرُوا وَاتَّجِرُوا، أَلَا وَإِنَّ هَذِهِ الْأَيَّامَ أَيَّامُ أَكْلٍ وَشُرْبٍ وَذِكْرِ اللهِ عَزَّ وَجَلَّ". (م,د,ن,جه)', 'നുബൈശത്(റ): റസൂൽ(സ) പറഞ്ഞു: "നിശ്ചയം, ഉള്ഹിയ്യത്തിന്റെ മാംസം നിങ്ങൾക്കെല്ലാവർക്കും ലഭ്യമാകാൻ വേണ്ടി മൂന്ന് ദിവസത്തേക്കാളധികം നിങ്ങളത് ഭക്ഷിക്കുന്നത് ഞാൻ വിലക്കിയിരുന്നു. നിശ്ചയം, ഇപ്പോൾ അല്ലാഹു സുഭിക്ഷത കൊണ്ടുവന്നിരിക്കുന്നു. അതിനാൽ നിങ്ങൾ ഭക്ഷിക്കുകയും സംഭരിച്ചുവെക്കുകയും കച്ചവടം ചെയ്യുകയും ചെയ്യുക. അറിയുക, നിശ്ചയം ഈ ദിനങ്ങൾ തീറ്റയുടെയും കുടിയുടെയും ദൈവ സ്മരണയുടെയും ദിനങ്ങളാണ്." (മു,ദ,ന,ജ)', 'نُبَيْشَةَ', 'നുബൈശത്(റ)', null, null, array['م','د','ن','جه']::text[], array['മു','ദ','ന','ജ']::text[], null, null, 904, 904, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=4 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 71, 'عَنْ سَلَمَةَ بْنِ الْأَكْوَعِ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ ضَحَّى مِنْكُمْ فَلَا يُصْبِحَنَّ بَعْدَ ثَالِثَةٍ وَبَقِيَ فِي بَيْتِهِ مِنْهُ شَيْءٌ". فَلَمَّا كَانَ الْعَامُ الْمُقْبِلُ قَالُوا: يَا رَسُولَ اللهِ، نَفْعَلُ كَمَا فَعَلْنَا عَامَ الْمَاضِي؟ قَالَ: "كُلُوا وَأَطْعِمُوا وَادَّخِرُوا، فَإِنَّ ذَلِكَ الْعَامَ كَانَ بِالنَّاسِ جَهْدٌ، فَأَرَدْتُ أَنْ تُعِينُوا فِيهَا". (ق)', 'സലമതുബ്നുൽ അക്വഅ്(റ): റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങളിലാരെങ്കിലും ഉള്ഹിയ്യത്തറുത്താൽ അതിൽനിന്ന് വല്ലതും അവന്റെ വീട്ടിൽ അവശേഷിക്കുന്നവനായി മൂന്നാമത്തെ ദിവസത്തിന് ശേഷം അവൻ പ്രഭാതമുണരരുത്." അടുത്ത വർഷമായപ്പോൾ അവർ ചോദിച്ചു: അല്ലാഹുവിന്റെ ദൂതരേ, കഴിഞ്ഞ വർഷം ചെയ്തതുപോലെ തന്നെയാണോ ഞങ്ങളീ വർഷവും ചെയ്യേണ്ടത്? റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങൾ ഭക്ഷിക്കുകയും ഭക്ഷിപ്പിക്കുകയും സംഭരിച്ചുവെക്കുകയും ചെയ്യുക. കാരണം, ആ കൊല്ലം ജനങ്ങൾക്ക് ക്ഷാമമായിരുന്നു. അതിനാൽ ആ വർഷം നിങ്ങൾ (പരസ്പരം) സഹായിക്കണമെന്ന് ഞാൻ ഉദ്ദേശിച്ചു." (ബു,മു)', 'سَلَمَةَ بْنِ الْأَكْوَعِ', 'സലമതുബ്നുൽ അക്വഅ്(റ)', null, null, array['ق']::text[], array['ബു','മു']::text[], null, null, 904, 904, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=4 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 72, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا يَأْكُلْ أَحَدُكُمْ مِنْ لَحْمِ أُضْحِيَّتِهِ فَوْقَ ثَلَاثَةِ أَيَّامٍ". (م,ت)', 'ഇബ്നുഉമർ(റ): റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങളിലൊരാളും തന്റെ ഉള്ഹിയ്യത്തിന്റെ മാംസം മൂന്ന് ദിവസത്തിനപ്പുറം ഭക്ഷിക്കരുത്." (മു,തു)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['م','ت']::text[], array['മു','തു']::text[], null, null, 904, 904, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=4 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 73, 'عَنْ بُرَيْدَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "كُنْتُ نَهَيْتُكُمْ عَنْ لُحُومِ الْأَضَاحِيِّ فَوْقَ ثَلَاثٍ، لِيَتَّسِعَ ذُو الطَّوْلِ عَلَى مَنْ لَا طَوْلَ لَهُ، فَكُلُوا مَا بَدَا لَكُمْ وَأَطْعِمُوا وَادَّخِرُوا". (م,ت)', 'ബുറൈദ(റ): റസൂൽ(സ) പറഞ്ഞു: "കഴിവുള്ളവൻ കഴിവില്ലാത്തവന് നൽകാൻ വേണ്ടി, ഉള്ഹിയ്യത്തിന്റെ മാംസം മൂന്ന് ദിവസത്തിന് ശേഷം ഭക്ഷിക്കുന്നത് നിങ്ങൾക്ക് ഞാൻ വിലക്കിയിരുന്നു. അതിനാൽ ഇനിമുതൽ നിങ്ങൾക്ക് ലഭിക്കുന്നത് നിങ്ങൾ ഭക്ഷിക്കുകയും ഭക്ഷിപ്പിക്കുകയും സംഭരിച്ചുവെക്കുകയും .ചെയ്യുക." (മു,തു)', 'بُرَيْدَةَ', 'ബുറൈദ(റ)', null, null, array['م','ت']::text[], array['മു','തു']::text[], null, null, 905, 905, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=4 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 74, 'عَنْ عَابِسِ بْنِ رَبِيعَةَ قَالَ: قُلْتُ لِأُمِّ الْمُؤْمِنِينَ – يَعْنِي عَائِشَةَ رَضِيَ اللهُ عَنْهَا – أَكَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَنْهَى عَنْ لُحُومِ الْأَضَاحِيِّ؟ قَالَتْ: لَا، وَلَكِنْ قَلَّ مَنْ كَانَ يُضَحِّي مِنَ النَّاسِ، فَأَحَبَّ أَنْ يُطْعِمَ مَنْ لَمْ يَكُنْ يُضَحِّي، وَلَقَدْ كُنَّا نَرْفَعُ الْكُرَاعَ فَنَأْكُلُهُ بَعْدَ عَشَرَةِ أَيَّامٍ. (ق,د,ت,ن,جه)', 'ആബിസുബ്നു റബീഅ(റ): ഉള്ഹിയ്യത്തിന്റെ മാംസം റസൂൽ(സ) വിലക്കാറുണ്ടായിരുന്നോ എന്ന് സത്യവിശ്വാസികളുടെ മാതാവായ ആഇഷ(റ)യോട് ഞാൻ ചോദിച്ചു. മഹതി പറഞ്ഞു: ഇല്ല. പക്ഷേ, ജനങ്ങളിൽ ഉള്ഹിയ്യത്തറുക്കുന്നവർ കുറഞ്ഞപ്പോൾ അറുക്കാത്തവർക്കും ഭക്ഷണം ലഭിക്കണമെന്ന് അവിടുന്ന് ആഗ്രഹിച്ചു. നിശ്ചയം ഞങ്ങൾ കുറക് സൂക്ഷിച്ചുവെക്കുകയും പത്ത് ദിവസങ്ങൾക്ക് ശേഷമത് ഭക്ഷിക്കുകയും ചെയ്യാറുണ്ടായിരുന്നു. (ബു,മു,ദ,തു,ന,ജ)', 'عَابِسِ بْنِ رَبِيعَةَ قَالَ', 'ആബിസുബ്നു റബീഅ(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 905, 905, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=4 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 75, 'عَنْ عَلِيِّ بْنِ أَبِي طَالِبٍ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَمَرَهُ أَنْ يَقْسِمَ بُدْنَهُ كُلَّهَا، لُحُومَهَا وَجُلُودَهَا وَجِلَالَهَا لِلْمَسَاكِينِ. (جه)', 'അലിയ്യുബ്നു അബീത്വാലിബ്(റ): റസൂൽ(സ) അദ്ദേഹത്തോട് ബലിമൃഗങ്ങളുടെ എല്ലാ ഭാഗവും പാവങ്ങൾക്ക് വീതിച്ചുകൊടുക്കാൻ കൽപിച്ചു: അവയുടെ മാംസവും തോലും ജീനിയും. (ജ)', 'عَلِيِّ بْنِ أَبِي طَالِبٍ', 'അലിയ്യുബ്നു അബീത്വാലിബ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 905, 905, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=18 where b.volume_id=4 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 76, 'عَنْ جَابِرِ بْنِ عَبْدِ اللهِ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَمَرَ مِنْ كُلِّ جَزُورٍ بِبَضْعَةٍ، فَجُعِلَتْ فِي قِدْرٍ، فَأَكَلُوا مِنَ اللَّحْمِ وَحَسَوْا مِنَ الْمَرَقِ. (جه)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): അറുക്കപ്പെടുന്ന ഓരോ മൃഗത്തിൽ നിന്നും ഓരോ കഷ്ണം മാംസമെടുക്കാൻ റസൂൽ(സ) കൽപിച്ചു. അപ്പോൾ അവ ഒരു കലത്തിലാക്കപ്പെട്ടു. അങ്ങനെയവർ മാംസം ഭക്ഷിക്കുകയും കറി അൽപാൽപമായി കുടിക്കുകയും ചെയ്തു. (ജ)', 'جَابِرِ بْنِ عَبْدِ اللهِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 905, 905, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=19 where b.volume_id=4 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 77, 'عَنْ جُنْدَبِ بْنِ سُفْيَانَ رَضِيَ اللهُ عَنْهُ قَالَ: شَهِدْتُ الْأَضْحَى مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَلَمْ يَعْدُ أَنْ صَلَّى وَفَرَغَ مِنْ صَلَاتِهِ سَلَّمَ، فَإِذَا هُوَ يَرَى لَحْمَ أَضَاحِيَّ قَدْ ذُبِحَتْ قَبْلَ أَنْ يَفْرُغَ مِنْ صَلَاتِهِ، فَقَالَ: "مَنْ كَانَ ذَبَحَ أُضْحِيَّتَهُ قَبْلَ أَنْ يُصَلِّيَ – أَوْ نُصَلِّيَ – فَلْيَذْبَحْ مَكَانَهَا أُخْرَى، وَمَنْ كَانَ لَمْ يَذْبَحْ فَلْيَذْبَحْ بِاسْمِ اللهِ". (ق,ن,جه)', 'ജുൻദുബുബ്നു സുഫ്യാൻ(റ): ഒരു ബലിപെരുന്നാളിൽ ഞാൻ റസൂൽ(സ)യോടൊപ്പം (നമസ്കാരത്തിൽ) പങ്കെടുത്തു. അവിടുന്ന് നമസ്കാരം നിർവ്വഹിക്കുകയും നമസ്കാരത്തിൽ നിന്ന് വിരമിച്ച് സലാം വീട്ടുകയും ചെയ്തയുടനെത്തന്നെ, നമസ്കാരം കഴിയുന്നതിന് മുമ്പേ അറുക്കപ്പെട്ട കുറെ ബലിമൃഗങ്ങളെ കണ്ടു. അപ്പോളവിടുന്ന് പറഞ്ഞു: "നാം നമസ്കരിക്കുന്നതിന് - അല്ലെങ്കിൽ: താൻ നമസ്കരിക്കുന്നതിന് - മുമ്പ് ബലിയറുത്തവൻ അതിന് പകരമായി മറ്റൊന്നിനെ അറുത്തുകൊള്ളട്ടെ. അറുത്തിട്ടില്ലാത്തവർ ബിസ്മി ചൊല്ലി അറുക്കുകയും ചെയ്യട്ടെ." (ബു,മു,ന,ജ)', 'جُنْدَبِ بْنِ سُفْيَانَ', 'ജുൻദുബുബ്നു സുഫ്യാൻ(റ)', null, null, array['ق','ن','جه']::text[], array['ബു','മു','ന','ജ']::text[], null, null, 905, 906, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=4 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 78, 'عَنِ الْبَرَاءِ بْنِ عَازِبٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ أَوَّلَ مَا نَبْدَأُ بِهِ فِي يَوْمِنَا هَذَا نُصَلِّي، ثُمَّ نَرْجِعُ فَنَنْحَرُ، فَمَنْ فَعَلَ ذَلِكَ فَقَدْ أَصَابَ سُنَّتَنَا، وَمَنْ ذَبَحَ فَإِنَّمَا هُوَ لَحْمٌ قَدَّمَهُ لِأَهْلِهِ، لَيْسَ مِنَ النُّسُكِ فِي شَيْءٍ". وَكَانَ أَبُو بُرْدَةَ بْنُ نِيَارٍ رَضِيَ اللهُ عَنْهُ قَدْ ذَبَحَ، فَقَالَ: عِنْدِي جَذَعَةٌ خَيْرٌ مِنْ مُسِنَّةٍ. فَقَالَ: "اذْبَحْهَا، وَلَنْ تَجْزِيَ عَنْ أَحَدٍ بَعْدَكَ". (ق)', 'ബറാഉബ്നു ആസിബ്(റ): റസൂൽ(സ) പറഞ്ഞു: "നമ്മുടെ ഈ ദിനത്തിൽ നാം ആദ്യമായി ചെയ്യേണ്ടത് നിസ്കരിക്കലാണ്. പിന്നെ മടങ്ങിവന്ന് അറുക്കലുമാണ്. ഇപ്രകാരം ചെയ്തവൻ തീർച്ചയായും നമ്മുടെ ചര്യ പിൻപറ്റിയിരിക്കുന്നു. നിസ്കാരത്തിന് മുമ്പ് ആരെങ്കിലും അറുത്തുവെങ്കിൽ അത് അവൻ അവന്റെ കുടുംബത്തിന് നൽകുന്ന മാംസം മാത്രമാണ്. അത് ആരാധനയിൽ പെടുന്നതല്ല." അബൂബുർദതുബ്നു നിയാർ(റ) നിസ്കാരത്തിന് മുമ്പേ അറുത്തിട്ടുണ്ടായിരുന്നു. അദ്ദേഹം പറഞ്ഞു: പല്ല് മുളച്ച മൃഗത്തേക്കാൾ ഉത്തമമായ, ആറ് മാസം തികയാത്ത ഒരു മൃഗം എന്റെ കയ്യിലുണ്ട്. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "നീ അതിനെ അറുക്കുക. നിങ്ങൾക്ക് ശേഷം മറ്റൊരാൾക്കും അത് മതിയാകുകയില്ല." (ബു,മു)', 'الْبَرَاءِ بْنِ عَازِبٍ', 'ബറാഉബ്നു ആസിബ്(റ)', null, null, array['ق']::text[], array['ബു','മു']::text[], null, null, 906, 906, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=4 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 79, 'عَنِ الْبَرَاءِ رَضِيَ اللهُ عَنْهُ قَالَ: قَامَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَوْمَ الْأَضْحَى فَقَالَ: "مَنْ وَجَّهَ قِبْلَتَنَا وَصَلَّى صَلَاتَنَا وَنَسَكَ نُسُكَنَا، فَلَا يَذْبَحْ حَتَّى يُصَلِّيَ". فَقَامَ خَالِي فَقَالَ: يَا رَسُولَ اللهِ، إِنِّي عَجَّلْتُ نُسُكِي لِأُطْعِمَ أَهْلِي وَأَهْلَ دَارِي؟ أَوْ: أَهْلِي وَجِيرَانِي؟ فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَعِدْ ذَبْحًا آخَرَ". قَالَ: فَإِنَّ عِنْدِي عَنَاقَ لَبَنٍ، هِيَ أَحَبُّ إِلَيَّ مِنْ شَاتَيْ لَحْمٍ. قَالَ: "فَإِنَّهَا خَيْرُ نَسِيكَتَيْكَ، وَلَا تَقْضِي جَذَعَةٌ عَنْ أَحَدٍ بَعْدَكَ". (ق,د,ت,ن)', 'ബറാഅ്(റ): ബലിദിനത്തിൽ എഴുന്നേറ്റുനിന്ന് റസൂൽ(സ) പറഞ്ഞു: "നമ്മുടെ ഖിബ്‌ലയിലേക്ക് മുഖം തിരിക്കുകയും നമ്മുടെ നിസ്കാരം നിർവഹിക്കുകയും നമ്മുടെ ആരാധനകൾ നടത്തുകയും ചെയ്യുന്നവർ, നിസ്കാരം കഴിയുന്നതുവരെ അറുക്കരുത്." അപ്പോൾ എന്റെ അമ്മാവൻ എഴുന്നേറ്റുനിന്ന് പറഞ്ഞു: അല്ലാഹുവിന്റെ ദൂതരേ, എന്റെ വീട്ടുകാരെയും കുടുംബത്തെയും - അല്ലെങ്കിൽ എന്റെ കുടുംബത്തെയും എന്റെ അയൽവാസികളെയും - ഭക്ഷിപ്പിക്കുന്നതിനായി എന്റെ അറവ് ഞാൻ ധൃതിയിൽ ചെയ്തുകഴിഞ്ഞിരിക്കുന്നു. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "നീ മറ്റൊരു അറവുകൂടി നടത്തുക." അദ്ദേഹം പറഞ്ഞു: തടിച്ച രണ്ട് ആടുകളേക്കാൾ എനിക്ക് ഇഷ്ടപ്പെട്ട, പാൽ കുടിക്കുന്ന ഒരു ഒട്ടകമെനിക്കുണ്ട്. റസൂൽ(സ) പറഞ്ഞു: "തീർച്ചയായും താങ്കളുടെ രണ്ട് ബലികളിൽ ഏറ്റവും ഉത്തമം അതാണ്. താങ്കൾക്കുശേഷം മറ്റൊരാൾക്കും പ്രായം കുറഞ്ഞ മൃഗം മതിയാവുന്നതല്ല." (ബു,മു,ദ,തു,ന)', 'الْبَرَاءِ', 'ബറാഅ്(റ)', null, null, array['ق','د','ت','ن']::text[], array['ബു','മു','ദ','തു','ന']::text[], null, null, 906, 906, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=4 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 80, 'عَنِ الْبَرَاءِ بْنِ عَازِبٍ رَضِيَ اللهُ عَنْهُ قَالَ: خَطَبَنَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَوْمَ النَّحْرِ بَعْدَ الصَّلَاةِ، ثُمَّ قَالَ: "مَنْ صَلَّى صَلَاتَنَا وَنَسَكَ نُسُكَنَا فَقَدْ أَصَابَ النُّسُكَ، وَمَنْ نَسَكَ قَبْلَ الصَّلَاةِ فَتِلْكَ شَاةُ لَحْمٍ". فَقَالَ أَبُو بُرْدَةَ: يَا رَسُولَ اللهِ، وَاللهِ لَقَدْ نَسَكْتُ قَبْلَ أَنْ أَخْرُجَ إِلَى الصَّلَاةِ، وَعَرَفْتُ أَنَّ الْيَوْمَ يَوْمُ أَكْلٍ وَشُرْبٍ، فَتَعَجَّلْتُ فَأَكَلْتُ وَأَطْعَمْتُ أَهْلِي وَجِيرَانِي؟ فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "تِلْكَ شَاةُ لَحْمٍ". قَالَ: فَإِنَّ عِنْدِي عَنَاقًا جَذَعَةً، خَيْرٌ مِنْ شَاتَيْ لَحْمٍ، فَهَلْ تُجْزِئُ عَنِّي؟ قَالَ: "نَعَمْ، وَلَنْ تَجْزِيَ عَنْ أَحَدٍ بَعْدَكَ". (ق,د,ت,ن)', 'ബറാഉബ്നു ആസിബ്(റ): ബലിദിനത്തിൽ നിസ്കാര ശേഷം റസൂൽ(സ) ഞങ്ങളോട് പ്രസംഗിച്ചു. ശേഷം പറഞ്ഞു: "നമ്മുടെ നിസ്കാരം നിർവഹിക്കുകയും നമ്മുടെ ആരാധന (ബലിയറുക്കൽ) നിർവ്വഹിക്കുകയും ചെയ്തവന് ബലിയറുക്കൽ ലഭിച്ചിരിക്കുന്നു. ആരെങ്കിലും നിസ്കാരത്തിന് മുമ്പ് അറുത്താൽ അത് ഇറച്ചിക്കുവേണ്ടി അറുക്കപ്പെട്ട ആടാണ്." അപ്പോൾ അബൂബുർദ(റ) പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, അല്ലാഹുവാണ് സത്യം, നിസ്കാരത്തിന് പുറപ്പെടുന്നതിന് മുമ്പ് ഞാൻ അറുത്തിരിക്കുന്നു. ഇന്ന് തീറ്റയുടെയും കുടിയുടെയും ദിവസമാണെന്ന് ഞാൻ അറിഞ്ഞിട്ടുള്ളതിനാൽ ഞാൻ ധൃതികൂട്ടുകയും ഞാനത് ഭക്ഷിക്കുകയും എന്റെ കുടുംബത്തെയും അയൽവാസികളെയും ഭക്ഷിപ്പിക്കുകയും ചെയ്തിരിക്കുന്നു. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "അത് മാംസത്തിന് വേണ്ടി അറുക്കപ്പെട്ട ആടാണ്." അദ്ദേഹം പറഞ്ഞു: നിശ്ചയം, തടിച്ച രണ്ട് ആടുകളേക്കാൾ മുന്തിയ പ്രായം കുറഞ്ഞ ഒരൊട്ടകം എന്റെ കയ്യിലുണ്ട്. ഞാനതിനെ അറുത്താൽ മതിയാകുമോ? റസൂൽ(സ) പറഞ്ഞു: "അതെ, നിങ്ങൾക്ക് ശേഷം ഒരാൾക്കും അത് മതിയാകുന്നതല്ല." (ബു,മു,ദ,തു,ന)', 'الْبَرَاءِ بْنِ عَازِبٍ', 'ബറാഉബ്നു ആസിബ്(റ)', null, null, array['ق','د','ت','ن']::text[], array['ബു','മു','ദ','തു','ന']::text[], null, null, 906, 907, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=4 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 81, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَوْمَ النَّحْرِ: "مَنْ كَانَ ذَبَحَ قَبْلَ الصَّلَاةِ فَلْيُعِدْ". فَقَامَ رَجُلٌ فَقَالَ: يَا رَسُولَ اللهِ، هَذَا يَوْمٌ يُشْتَهَى فِيهِ اللَّحْمُ. فَذَكَرَ هَنَةً مِنْ جِيرَانِهِ، كَأَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ صَدَّقَهُ، قَالَ: عِنْدِي جَذَعَةٌ هِيَ أَحَبُّ إِلَيَّ مِنْ شَاتَيْ لَحْمٍ. فَرَخَّصَ لَهُ، فَلَا أَدْرِي: أَبَلَغَتْ رُخْصَتُهُ مَنْ سِوَاهُ أَمْ لَا؟ ثُمَّ انْكَفَأَ إِلَى كَبْشَيْنِ فَذَبَحَهُمَا. (خ,ن)', 'അനസ്(റ): അറവുദിനത്തിൽ റസൂൽ(സ) പറഞ്ഞു: "നിസ്കാരത്തിന് മുമ്പ് അറവ് നടത്തിയവർ മടക്കി അറുക്കട്ടെ." അപ്പോൾ ഒരാൾ എഴുന്നേറ്റുനിന്ന് പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, ഇത് മാംസം കൊതിക്കപ്പെടുന്ന ദിവസമാണല്ലോ. എന്നിട്ടദ്ദേഹം തന്റെ അയൽവാസികളുടെ കൊതിയെപ്പറ്റി പറഞ്ഞു. റസൂൽ(സ) അദ്ദേഹത്തെ ശരിവെച്ചതു പോലെയുണ്ട്. ശേഷം അദ്ദേഹം പറഞ്ഞു: തടിച്ച രണ്ട് ആടുകളേക്കാൾ എനിക്കിഷ്ടപ്പെട്ട പ്രായം കുറഞ്ഞ ഒരു മൃഗം എന്റെ കയ്യിലുണ്ട്. അപ്പോൾ റസൂൽ(സ) അദ്ദേഹത്തിനതിൽ ഇളവ് നൽകി. അദ്ദേഹമല്ലാത്തവർക്ക് ആ ഇളവ് ലഭിക്കുമോ ഇല്ലയോ എന്നെനിക്കറിയില്ല. ശേഷമവിടുന്ന് രണ്ട് ആടുകളെ എടുത്ത് അവയെ അറുത്തു. (ബു,ന)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['خ','ن']::text[], array['ബു','ന']::text[], null, null, 907, 907, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=4 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 82, 'عَنْ أَبِي بُرْدَةَ بْنِ نِيَارٍ رَضِيَ اللهُ عَنْهُ: أَنَّهُ ذَبَحَ قَبْلَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَأَمَرَهُ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنْ يُعِيدَ، قَالَ: عِنْدِي عَنَاقُ جَذَعَةٍ هِيَ أَحَبُّ إِلَيَّ مِنْ مُسِنَّتَيْنِ. قَالَ: "اذْبَحْهَا". (ن)', 'അബൂബുർദതുബ്നു നിയാർ(റ): അദ്ദേഹം നബി(സ) അറുക്കുന്നതിന് മുമ്പ് അറുത്തു. അപ്പോൾ അദ്ദേഹത്തോട് നബി(സ) മടക്കി അറുക്കാൻ കൽപിച്ചു. അദ്ദേഹം പറഞ്ഞു: പല്ലുകൾ മുളച്ച വലിയ രണ്ട് മൃഗങ്ങളേക്കാൾ എനിക്കിഷ്ടപ്പെട്ട, പ്രായം കുറഞ്ഞ ഒരു ഒട്ടകം എന്റെ കയ്യിലുണ്ട്. നബി(സ) പറഞ്ഞു: "നീയതിനെ അറുക്കുക." (ന)', 'أَبِي بُرْدَةَ بْنِ نِيَارٍ', 'അബൂബുർദതുബ്നു നിയാർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 907, 907, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=4 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 83, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ: أَنَّ رَجُلًا ذَبَحَ يَوْمَ النَّحْرِ، يَعْنِي: قَبْلَ الصَّلَاةِ، فَأَمَرَهُ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنْ يُعِيدَ. (ق,ن,جه)', 'അനസുബ്നു മാലിക്(റ): നിശ്ചയം ഒരാൾ ബലിദിനത്തിൽ അറുത്തു, അതായത് നിസ്കാരത്തിന് മുമ്പ്. അപ്പോൾ നബി(സ) അയാളോട് മടക്കിയറുക്കുവാൻ കൽപിച്ചു. (ബു,മു,ന,ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['ق','ن','جه']::text[], array['ബു','മു','ന','ജ']::text[], null, null, 907, 907, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=4 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 84, 'عَنْ عُوَيْمِرِ بْنِ أَشْقَرَ رَضِيَ اللهُ عَنْهُ: أَنَّهُ ذَبَحَ قَبْلَ الصَّلَاةِ، فَذَكَرَهُ لِلنَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: "أَعِدْ أُضْحِيَّتَكَ". [ز: في سنده انقطاع] (جه)', 'ഉവൈമിറുബ്നു അശ്കർ(റ): അദ്ദേഹം നിസ്കാരത്തിന് മുമ്പ് അറുക്കുകയും അത് നബി(സ)യോട് പറയുകയും ചെയ്തു. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങളുടെ ബലിയറുക്കൽ നിങ്ങൾ മടക്കി ചെയ്യുക." ഇതിന്റെ പരമ്പരയിൽ ഭംഗമുണ്ട്. (ജ)', 'عُوَيْمِرِ بْنِ أَشْقَرَ', 'ഉവൈമിറുബ്നു അശ്കർ(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في سنده انقطاع', null, 908, 908, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=4 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 85, 'عَنْ أَبِي زَيْدٍ الْأَنْصَارِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: مَرَّ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِدَارٍ مِنْ دُورِ الْأَنْصَارِ، فَوَجَدَ رِيحَ قُتَارٍ، فَقَالَ: "مَنْ هَذَا الَّذِي ذَبَحَ". فَخَرَجَ إِلَيْهِ رَجُلٌ مِنَّا فَقَالَ: أَنَا يَا رَسُولَ اللهِ، ذَبَحْتُ قَبْلَ أَنْ أُصَلِّيَ لِأُطْعِمَ أَهْلِي وَجِيرَانِي، فَأَمَرَهُ أَنْ يُعِيدَ، فَقَالَ: لَا، وَاللهِ الَّذِي لَا إِلَهَ إِلَّا هُوَ، مَا عِنْدِي إِلَّا جَذَعٌ – أَوْ: حَمَلٌ – مِنَ الضَّأْنِ. قَالَ: "اذْبَحْهَا، وَلَنْ تُجْزِئَ جَذَعَةٌ عَنْ أَحَدٍ بَعْدَكَ". (جه)', 'അബൂസൈദിൽ അൻസാരി(റ): അൻസാരികളുടെ വീടുകളിലെ ഒരു വീടിന്നടുത്തുകൂടെ നബി(സ) നടന്നുപോവുകയും വേവിക്കപ്പെടുന്ന മാംസത്തിന്റെ വാസന ലഭിക്കുകയും ചെയ്തു. അവിടുന്ന് ചോദിച്ചു: "ആരാണ് അറുത്തവൻ?" അപ്പോൾ ഞങ്ങളിൽ നിന്നൊരാൾ വന്ന് പറഞ്ഞു: ഞാനാണ് റസൂലേ. എന്റെ വീട്ടുകാരെയും അയൽവാസികളെയും ഭക്ഷിപ്പിക്കാൻ വേണ്ടി നിസ്കരിക്കുന്നതിന് മുമ്പേ ഞാൻ അറുത്തു. അവിടുന്നദ്ദേഹത്തോട് മടക്കി അറുക്കാൻ കൽപിച്ചു. അപ്പോഴദ്ദേഹം പറഞ്ഞു: ആരാധ്യനായ അല്ലാഹുവാണ് സത്യം, ആറുമാസം പ്രായമായ - അല്ലെങ്കിൽ: അതിനേക്കാൾ പ്രായം കുറഞ്ഞ - ഒരു ചെമ്മരിയാട് അല്ലാതെ മറ്റൊന്നും എന്റടുത്തില്ല. റസൂൽ(സ) പറഞ്ഞു: "നീയതിനെ അറുക്കുക. നിനക്ക് ശേഷം മറ്റൊരാൾക്കും പ്രായം കുറഞ്ഞ മൃഗം മതിയാകുന്നതല്ല." (ജ)', 'أَبِي زَيْدٍ الْأَنْصَارِيِّ', 'അബൂസൈദിൽ അൻസാരി(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 908, 908, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=4 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 86, 'عَنِ الْبَرَاءِ بْنِ عَازِبٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: ضَحَّى خَالٌ لِي – يُقَالُ لَهُ: أَبُو بُرْدَةَ – قَبْلَ الصَّلَاةِ، فَقَالَ لَهُ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "شَاتُكَ شَاةُ لَحْمٍ". فَقَالَ: يَا رَسُولَ اللهِ، إِنَّ عِنْدِي دَاجِنًا، جَذَعَةً مِنَ الْمَعْزِ؟ فَقَالَ: "اذْبَحْهَا، وَلَا تَصْلُحُ لِغَيْرِكَ". (ق,د,ن)', 'ബറാഉബ്നു ആസിബ്(റ): അബൂബുർദ(റ) എന്ന് പേരുള്ള എന്റെയൊരു അമ്മാവൻ നിസ്കാരത്തിന് മുമ്പ് ഉള്ഹിയ്യത്തറുത്തു. അപ്പോൾ റസൂൽ(സ) അദ്ദേഹത്തോട് പറഞ്ഞു: "നിങ്ങളുടെ ആട് മാംസത്തിന് വേണ്ടി അറുക്കപ്പെട്ട ആടാണ്." അദ്ദേഹം പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, വീട്ടിൽ വളർത്തുന്ന പ്രായം കുറഞ്ഞ ഒരു കോലാട് എന്റടുത്തുണ്ട്. റസൂൽ(സ) പറഞ്ഞു: "നീയതിനെ അറുക്കുക. നീയല്ലാത്തവർക്കത് പറ്റുകയില്ല." (ബു,മു,ദ,ന)', 'الْبَرَاءِ بْنِ عَازِبٍ', 'ബറാഉബ്നു ആസിബ്(റ)', null, null, array['ق','د','ن']::text[], array['ബു','മു','ദ','ന']::text[], null, null, 908, 908, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=4 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 87, 'عَنْ أَبِي بَكْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ خَطَبَ، ثُمَّ نَزَلَ فَدَعَا بِكَبْشَيْنِ فَذَبَحَهُمَا. (ت)', 'അബൂബക്റഃ(റ): നബി(സ) ഖുത്വുബ നിർവ്വഹിച്ചു. ശേഷം ഇറങ്ങിവന്ന് രണ്ട് കൊറ്റനാടുകളെ കൊണ്ടുവരാൻ കൽപിക്കുകയും അവയെ അറുക്കുകയും ചെയ്തു. (തു)', 'أَبِي بَكْرَةَ', 'അബൂബക്റഃ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 908, 908, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=4 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 88, 'عَنْ جَابِرِ بْنِ عَبْدِ اللهِ رَضِيَ اللهُ عَنْهُمَا قَالَ: شَهِدْتُ مَعَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ الْأَضْحَى بِالْمُصَلَّى، فَلَمَّا قَضَى خُطْبَتَهُ نَزَلَ عَنْ مِنْبَرِهِ، فَأُتِيَ بِكَبْشٍ، فَذَبَحَهُ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِيَدِهِ وَقَالَ: "بِسْمِ اللهِ وَاللهُ أَكْبَرُ، هَذَا عَنِّي وَعَمَّنْ لَمْ يُضَحِّ مِنْ أُمَّتِي". (د,ت)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): നിസ്കാര സ്ഥലത്തുവെച്ച് ഉള്ഹിയ്യത്തിൽ റസൂൽ(സ)യോടൊപ്പം ഞാൻ പങ്കെടുത്തു. ഖുത്വുബ കഴിഞ്ഞപ്പോൾ നബി(സ) മിമ്പറിൽ നിന്നിറങ്ങുകയും അപ്പോൾ ഒരാടിനെ കൊണ്ടുവരപ്പെടുകയും അവിടുന്നതിനെ സ്വന്തം കൈകൊണ്ട് അറുക്കുകയും ഇപ്രകാരം പറയുകയും ചെയ്തു: "ബിസ്മില്ലാഹി വല്ലാഹു അക്ബർ (അല്ലാഹുവിന്റെ നാമത്തിൽ, അല്ലാഹു മഹോന്നതനാണ്), ഇത് എന്റെയും എന്റെ സമുദായത്തിലെ ഉള്ഹിയ്യത്തറുക്കാത്തവരുടെയും പേരിലാണ്." (ദ,തു)', 'جَابِرِ بْنِ عَبْدِ اللهِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 908, 909, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=4 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 89, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يَذْبَحُ أُضْحِيَّتَهُ بِالْمُصَلَّى، وَكَانَ ابْنُ عُمَرَ يَفْعَلُهُ. (خ,د,ن,جه)', 'ഇബ്നുഉമർ(റ): നബി(സ) നിസ്കാരസ്ഥലത്തുവെച്ച് തന്നെ ഉള്ഹിയ്യത്തറുക്കാറുണ്ടായിരുന്നു. ഇബ്നു ഉമർ(റ)വും ഇപ്രകാരം ചെയ്യാറുണ്ടായിരുന്നു. (ബു,ദ,ന,ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['خ','د','ن','جه']::text[], array['ബു','ദ','ന','ജ']::text[], null, null, 909, 909, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=4 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 90, 'عَنْ عَبْدِ اللهِ بْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ نَحَرَ يَوْمَ الْأَضْحَى بِالْمَدِينَةِ، قَالَ: وَقَدْ كَانَ إِذَا لَمْ يَنْحَرْ يَذْبَحُ بِالْمُصَلَّى. (خ,د,ن,جه)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): റസൂൽ(സ) ബലിദിനത്തിൽ മദീനയിൽ വെച്ച് അറവ് നടത്തി. നിവേദകൻ പറയുന്നു: നബി(സ) (വീട്ടിൽവെച്ച്) ഒട്ടകത്തെ അറുത്തിട്ടില്ലെങ്കിൽ (ആടിനെയോ അതുപോലുള്ളതിനെയോ) നിസ്കാരസ്ഥലത്തുവെച്ച് അറുക്കുമായിരുന്നു. (ബു,ദ,ന,ജ)', 'عَبْدِ اللهِ بْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['خ','د','ن','جه']::text[], array['ബു','ദ','ന','ജ']::text[], null, null, 909, 909, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=4 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 91, 'عَنْ سَلْمَانَ بْنِ عَامِرٍ الضَّبِّيِّ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "مَعَ الْغُلَامِ عَقِيقَةٌ، فَأَهْرِيقُوا عَنْهُ دَمًا، وَأَمِيطُوا عَنْهُ الْأَذَى". (خ,د,ت,ن,جه)', 'സൽമാനുബ്നു ആമിരിള്ളബ്ബി(റ): റസൂൽ(സ) പറയുന്നതായി ഞാൻ കേട്ടു: "കുട്ടിയോടൊപ്പം പ്രസവമുടിയുണ്ട്. അതിനാൽ നിങ്ങൾ കുട്ടിയുടെ പേരിൽ അറുക്കുകയും കുട്ടികളെത്തൊട്ട് ബുദ്ധിമുട്ടുകൾ നീക്കംചെയ്യുകയും ചെയ്യുക." (ബു,ദ,തു,ന,ജ)', 'سَلْمَانَ بْنِ عَامِرٍ الضَّبِّيِّ', 'സൽമാനുബ്നു ആമിരിള്ളബ്ബി(റ)', null, null, array['خ','د','ت','ن','جه']::text[], array['ബു','ദ','തു','ന','ജ']::text[], null, null, 909, 909, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=4 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 92, 'عَنْ أُمِّ كُرْزٍ رَضِيَ اللهُ عَنْهَا قَالَتْ: أَتَيْتُ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِالْحُدَيْبِيَةِ أَسْأَلُهُ عَنْ لُحُومِ الْهَدْيِ، فَسَمِعْتُهُ يَقُولُ: "عَلَى – عَنِ – الْغُلَامِ شَاتَانِ، وَعَلَى – عَنِ – الْجَارِيَةِ شَاةٌ، لَا يَضُرُّكُمْ ذُكْرَانًا كُنَّ أَمْ إِنَاثًا". (د,ت,ن,جه)', 'ഉമ്മുകുർസ്(റ): ബലിയറുക്കപ്പെടുന്നതിന്റെ മാംസത്തെക്കുറിച്ച് ചോദിക്കാനായി ഹുദൈബിയ്യയിൽ വെച്ച് ഞാൻ റസൂൽ(സ)യെ സമീപിച്ചു. അപ്പോൾ അവിടുന്നിപ്രകാരം പറയുന്നത് ഞാൻ കേട്ടു: "ആൺകുട്ടിക്ക് രണ്ട് ആടുകളും പെൺകുട്ടിക്ക് ഒരാടുമാണ്. അവ ആണാടോ പെണ്ണാടോ എന്നത് നിങ്ങളെ ബുധിമുട്ടിക്കില്ല." (ദ,തു,ന,ജ)', 'أُمِّ كُرْزٍ', 'ഉമ്മുകുർസ്(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 909, 909, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=4 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 93, 'عَنْ أُمِّ كُرْزٍ رَضِيَ اللهُ عَنْهَا قَالَتْ: سَمِعْتُ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "أَقِرُّوا الطَّيْرَ عَلَى مَكِنَاتِهَا" قَالَتْ: وَسَمِعْتُهُ يَقُولُ: "عَنِ الْغُلَامِ شَاتَانِ، وَعَنِ الْجَارِيَةِ شَاةٌ، لَا يَضُرُّكُمْ أَذُكْرَانًا كُنَّ أَمْ إِنَاثًا". (د)', 'ഉമ്മുകുർസ്(റ): നബി(സ) പറയുന്നത് ഞാൻ കേട്ടു: "പക്ഷിയെ അത് വന്നിരിക്കുന്ന സ്ഥലത്തുതന്നെ ഇരുത്തുക (അതുമായി ലക്ഷണം നോക്കരുത്)." മഹതി പറയുന്നു: നബി(സ) ഇപ്രകാരം പറയുന്നതായും ഞാൻ കേട്ടു: "ആൺകുട്ടിക്ക് രണ്ട് ആടുകളും പെൺകുട്ടിക്ക് ഒരാടുമാണ്. അവ ആണോ പെണ്ണോ എന്നത് നിങ്ങളെ ബുദ്ധിമുട്ടിക്കില്ല." (ദ)', 'أُمِّ كُرْزٍ', 'ഉമ്മുകുർസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 909, 910, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=4 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 94, 'عَنْ سَمُرَةَ بْنِ جُنْدُبٍ رَضِيَ اللهُ عَنْهُ، عَنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "كُلُّ غُلَامٍ رَهِينَةٌ بِعَقِيقَتِهِ، تُذْبَحُ عَنْهُ يَوْمَ السَّابِعِ – وَفِي رِوَايَةٍ: سَابِعَهُ – وَيُحْلَقُ رَأْسُهُ وَيُدَمَّى". وَفِي رِوَايَةٍ: "وَيُسَمَّى". (د,ت,ن,جه)', 'സമുറതുബ്നു ജുൻദുബ്(റ): റസൂൽ(സ) പറഞ്ഞു: "ഓരോ കുട്ടിയും അവന്റെ അഖീഖത്തിന് പണയപ്പെടുത്തപ്പെട്ടവനാണ്. ഏഴാമത്തെ ദിവസം അവന്റെ പേരിൽ അറുക്കപ്പെടുകയും അവന്റെ തലമുടി നീക്കപ്പെടുകയും രക്തം ഒലിപ്പിക്കപ്പെടുകയും വേണം." മറ്റൊരു നിവേദനം: "പേര് വിളിക്കപ്പെടുകയും വേണം." (ദ,തു,ന,ജ)', 'سَمُرَةَ بْنِ جُنْدُبٍ', 'സമുറതുബ്നു ജുൻദുബ്(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 910, 910, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=4 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=4 and b.book_no=17 and h.hadith_no=94), 1, 'وَفِي رِوَايَةٍ: سَابِعَهُ – وَيُحْلَقُ رَأْسُهُ وَيُدَمَّى".', 'മറ്റൊരു നിവേദനം: "പേര് വിളിക്കപ്പെടുകയും വേണം." (ദ,തു,ന,ജ)');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=4 and b.book_no=17 and h.hadith_no=94), 2, 'وَفِي رِوَايَةٍ: "وَيُسَمَّى". (د,ت,ن,جه)', null);
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 95, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: أَمَرَنَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنْ نَعُقَّ عَنِ الْغُلَامِ شَاتَيْنِ، وَعَنِ الْجَارِيَةِ شَاةً. (ت,جه)', 'ആഇശ(റ): ആൺകുട്ടിക്ക് രണ്ടാടുകളെയും പെൺകുട്ടിക്ക് ഒരാടിനെയും അഖീഖത്തറുക്കാൻ റസൂൽ(സ) ഞങ്ങളോട് കൽപിച്ചു. (തു,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 910, 910, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=4 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 96, 'عَنْ يَزِيدَ بْنِ عَبْدٍ الْمُزَنِيِّ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "يُعَقُّ عَنِ الْغُلَامِ، وَلَا يُمَسُّ رَأْسُهُ بِدَمٍ". (جه)', 'യസീദുബ്നു അബ്ദിൽ മുസ്നി(റ): നിശ്ചയം റസൂൽ(സ) പറഞ്ഞു: "കുട്ടിയുടെ പേരിൽ അഖീഖത്തറുക്കപ്പെടണം. അവന്റെ തലയിൽ രക്തം പുരട്ടപ്പെടരുത്." (ജ)', 'يَزِيدَ بْنِ عَبْدٍ الْمُزَنِيِّ', 'യസീദുബ്നു അബ്ദിൽ മുസ്നി(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 910, 910, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=4 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 97, 'عَنِ الْحَسَنِ: أَنَّهُ كَانَ يَقُولُ: إِمَاطَةُ الْأَذَى حَلْقُ الرَّأْسِ. (د)', 'ഹസൻ(റ): അദ്ദേഹം ഇപ്രകാരം പറയാറുണ്ടായിരുന്നു: ബുദ്ധിമുട്ടുകൾ നീക്കം ചെയ്യലെന്നാൽ തല മുണ്ധനം ചെയ്യലാണ്. (ദ)', 'الْحَسَنِ', 'ഹസൻ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 910, 910, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=4 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 98, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَقَّ عَنِ الْحَسَنِ وَالْحُسَيْنِ رَضِيَ اللهُ عَنْهُمَا كَبْشًا كَبْشًا. (د,ن)', 'ഇബ്നുഅബ്ബാസ്(റ): റസൂൽ(സ) ഹസൻ(റ)വിന്റെയും ഹുസൈൻ(റ)വിന്റെയും പേരിൽ ഓരോ ആടുകളെ വീതം അഖീഖത്തറുത്തു. (ദ,ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 910, 910, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=4 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 99, 'عَنْ عَبْدِاللهِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُمَا قَالَ: سُئِلَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَنِ الْعَقِيقَةِ، فَقَالَ: "لَا يُحِبُّ اللهُ الْعُقُوقَ". كَأَنَّهُ كَرِهَ الِاسْمَ، وَقَالَ: "مَنْ وُلِدَ لَهُ وَلَدٌ، فَأَحَبَّ أَنْ يَنْسُكَ عَنْهُ فَلْيَنْسُكْ: عَنِ الْغُلَامِ شَاتَانِ مُكَافِئَتَانِ، وَعَنِ الْجَارِيَةِ شَاةٌ". وَسُئِلَ عَنِ الْفَرَعِ، قَالَ: "وَالْفَرَعُ حَقٌّ، وَأَنْ تَتْرُكُوهُ حَتَّى يَكُونَ بَكْرًا شُغْزُبًّا، ابْنَ مَخَاضٍ أَوِ ابْنَ لَبُونٍ، فَتُعْطِيَهُ أَرْمَلَةً أَوْ تَحْمِلَ عَلَيْهِ فِي سَبِيلِ اللهِ، خَيْرٌ مِنْ أَنْ تَذْبَحَهُ فَيَلْزَقَ لَحْمُهُ بِوَبَرِهِ، وَتَكْفَأَ إِنَاءَكَ وَتُولِهَ نَاقَتَكَ". (د,ت,ن,جه)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): റസൂൽ(സ) അഖീഖത്തിനെക്കുറിച്ച് ചോദിക്കപ്പെട്ടു. അപ്പോളവിടുന്ന് പറഞ്ഞു: "അനുസരണക്കേട് അല്ലാഹു ഇഷ്ടപ്പെടുന്നില്ല." അവിടുത്തേക്ക് ആ പേര് ഇഷ്ടപ്പെടാത്തതുപോലെയുണ്ട്. അവിടുന്ന് പറഞ്ഞു: "ആർക്കെങ്കിലും ഒരു കുഞ്ഞ് ജനിക്കുകയും ആ കുഞ്ഞിന് വേണ്ടി അറവ് നടത്താൻ ആഗ്രഹിക്കുകയും ചെയ്താൽ അവനത് ചെയ്തുകൊള്ളട്ടെ. ആൺകുട്ടിക്ക് ഒരേപോലെയുള്ള രണ്ടാടുകളും പെൺകുട്ടിക്ക് ഒരാടുമാണ് അറുക്കേണ്ടത്." മൃഗത്തിന്റെ കടിഞ്ഞൂലിനെക്കുറിച്ചും അവിടുന്ന് ചോദിക്കപ്പെട്ടു. അവിടുന്ന് പറഞ്ഞു: "കടിഞ്ഞൂലിനെ അറുക്കൽ ബാധ്യതയാണ്. എന്നാൽ മാംസമുറച്ച രണ്ടു വയസ്സുള്ള ആണൊട്ടകമോ പെണ്ണൊട്ടകമോ ആയി വളരുംവരെ അതിനെ ഒഴിച്ചിടുകയും, ശേഷമതിനെ ഒരു വിധവക്ക് നൽകുകയോ അല്ലെങ്കിൽ അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിലുള്ള പോരാട്ടത്തിനായി ഉപയോഗിക്കുകയോ ചെയ്യുന്നതാണ്, അതിനെ നീ അറുത്ത് അതിന്റെ മാംസം രോമവുമായി ചേരുന്നതിനേക്കാളും, നിന്റെ (പാൽ) പാത്രം കമിഴ്തി വെക്കുന്നതിനേക്കാളും നിന്റെ ഒട്ടകത്തെ വേദനിപ്പിക്കുന്നതിനേക്കാളും ഉത്തമം." (ദ,തു,ന,ജ)', 'عَبْدِاللهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 910, 911, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=4 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 100, 'عَنْ بُرَيْدَةَ رَضِيَ اللهُ عَنْهُ قَالَ: كُنَّا فِي الْجَاهِلِيَّةِ إِذَا وُلِدَ لِأَحَدِنَا غُلَامٌ ذَبَحَ شَاةً، وَلَطَخَ رَأْسَهُ بِدَمِهَا، فَلَمَّا جَاءَ اللهُ بِالْإِسْلَامِ كُنَّا نَذْبَحُ شَاةً، وَنَحْلِقُ رَأْسَهُ وَنُلَطِّخُهُ بِزَعْفَرَانٍ. (د)', 'ബുറൈദ(റ): ജാഹിലിയ്യാ കാലത്ത് ഞങ്ങളിലൊരാൾക്ക് ഒരു കുഞ്ഞ് പിറന്നാൽ അയാളൊരു ആടിനെ അറുക്കുകയും അതിന്റെ രക്തം കുട്ടിയുടെ തലയിൽ പുരട്ടുകയും ചെയ്യുമായിരുന്നു. അല്ലാഹു ഇസ്ലാം കൊണ്ടുവന്നപ്പോൾ ഞങ്ങൾ ആടിനെ അറുക്കുകയും കുട്ടിയുടെ തല മുണ്ഡനം ചെയ്യുകയും തലയിൽ കുങ്കുമം പുരട്ടുകയും ചെയ്യുമായിരുന്നു. (ദ)', 'بُرَيْدَةَ', 'ബുറൈദ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 911, 911, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=4 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 101, 'عَنْ عَلِيِّ بْنِ أَبِي طَالِبٍ رَضِيَ اللهُ عَنْهُ قَالَ: عَقَّ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَنِ الْحَسَنِ رَضِيَ اللهُ عَنْهُ بِشَاةٍ، وَقَالَ: "يَا فَاطِمَةُ، احْلِقِي رَأْسَهُ، وَتَصَدَّقِي بِزِنَةِ شَعْرِهِ فِضَّةً". قَالَ: فَوَزَنْتُهُ، فَكَانَ وَزْنُهُ دِرْهَمًا أَوْ بَعْضَ دِرْهَمٍ. حسن. (ت)', 'അലിയ്യുബ്നു അബീത്വാലിബ്(റ): റസൂൽ(സ) ഹസൻ(റ)വിന്റെ പേരിൽ ഒരാടിനെ അഖീഖത്തറുക്കുകയും ഇപ്രകാരം പറയുകയും ചെയ്തു: "ഫാത്വിമാ, നീ ഹസന്റെ തല മുണ്ഡനം ചെയ്യുകയും മുടിയുടെ തൂക്കത്തിനനുസരിച്ച് വെള്ളി ദാനം ചെയ്യുകയും ചെയ്യുക." അലി(റ) പറയുന്നു: അപ്പോൾ മഹതിയത് തൂക്കിനോക്കി. അതിന്റെ തൂക്കം ഒരു ദിർഹമോ അതിൽ താഴെയോ ആയിരുന്നു. ഹദീസ് ഹസനാണ്. (തു)', 'عَلِيِّ بْنِ أَبِي طَالِبٍ', 'അലിയ്യുബ്നു അബീത്വാലിബ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 911, 911, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=4 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 102, 'عَنْ أَبِي مُوسَى رَضِيَ اللهُ عَنْهُ قَالَ: وُلِدَ لِي غُلَامٌ، فَأَتَيْتُ بِهِ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَسَمَّاهُ إِبْرَاهِيمَ، فَحَنَّكَهُ بِتَمْرَةٍ وَدَعَا لَهُ بِالْبَرَكَةِ، وَدَفَعَهُ إِلَيَّ. (خ)', 'അബൂമൂസാ(റ): എനിക്കൊരു കുഞ്ഞ് ജനിക്കുകയും ഞാനവനുമായി റസൂൽ(സ)യുടെ അടുക്കൽ പോവുകയും ചെയ്തു. അപ്പോൾ അവിടുന്നവന് ഇബ്റാഹീം എന്ന് പേരിടുകയും കാരക്കകൊണ്ട് അവന് മധുരം നൽകുകയും അവന് ബറകത്തിന് വേണ്ടി പ്രാർത്ഥിക്കുകയും ശേഷം എനിക്ക് നൽകുകയും ചെയ്തു. (ബു)', 'أَبِي مُوسَى', 'അബൂമൂസാ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 911, 911, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=23 where b.volume_id=4 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 103, 'عَنْ أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّهَا حَمَلَتْ بِعَبْدِاللهِ بْنِ الزُّبَيْرِ، وَقَدْ تَقَدَّمَ فِي حَدِيثِ الْهِجْرَةِ، وَزَادَ هُنَا: فَفَرِحُوا بِهِ فَرَحًا شَدِيدًا، لِأَنَّهُمْ قِيلَ لَهُمْ: إِنَّ الْيَهُودَ قَدْ سَحَرَتْكُمْ، فَلَا يُولَدُ لَكُمْ. (خ)', 'അസ്മാഉബിൻത് അബൂബകർ(റ): മഹതി അബ്ദുല്ലാഹിബ്നു സുബൈർ(റ)വിനെ ഗർഭം ധരിച്ചു. ഹിജ്റയെ സംബന്ധിച്ച അധ്യായത്തിൽ ഈ ഹദീസ് വന്നിട്ടുണ്ട്. ഇവിടെ ഇതുകൂടി അധികമായുണ്ട്: അങ്ങനെ അക്കാരണത്താലവർ വളരെയധികം സന്തോഷിച്ചു. കാരണം അവരോടിപ്രകാരം പറയപ്പെട്ടിട്ടുണ്ടായിരുന്നു: നിശ്ചയം യഹൂദികൾ നിങ്ങൾക്ക് മാരണം ചെയ്തിരിക്കുന്നു. അതിനാൽ നിങ്ങൾക്ക് സന്താനങ്ങളുണ്ടാകുന്നതല്ല. (ബു)', 'أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ', 'അസ്മാഉബിൻത് അബൂബകർ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 911, 911, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=23 where b.volume_id=4 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 104, 'عَنْ أَبِي رَافِعٍ رَضِيَ اللهُ عَنْهُ قَالَ: رَأَيْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَذَّنَ فِي أُذُنِ الْحَسَنِ بْنِ عَلِيٍّ رَضِيَ اللهُ عَنْهُمَا حِينَ وَلَدَتْهُ فَاطِمَةُ رَضِيَ اللهُ عَنْهَا بِالصَّلَاةِ. (د,ت)', 'അബൂറാഫിഅ്(റ): ഫാത്വിമ ബീവി(റ) ഹസനുബ്നു അലി(റ)വിനെ പ്രസവിച്ച സമയത്ത് റസൂൽ(സ) ഹസൻ(റ)വിന്റെ ചെവിയിൽ നിസ്കാരത്തിനുള്ള ബാങ്ക് വിളിക്കുന്നത് ഞാൻ കണ്ടു. (ദ,തു)', 'أَبِي رَافِعٍ', 'അബൂറാഫിഅ്(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 912, 912, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=24 where b.volume_id=4 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 105, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا فَرَعَ وَلَا عَتِيرَةَ". وَفِي رِوَايَةٍ: نَهَى رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَنِ الْفَرَعِ وَالْعَتِيرَةِ. (ق,د,ن,جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "മൃഗത്തിന്റെ കടിഞ്ഞൂലിനെ അറുക്കലും റജബ് മാസത്തിലെ അറവുമില്ല." മറ്റൊരു നിവേദനം: മൃഗത്തിന്റെ കടിഞ്ഞൂലിനെ അറുക്കലും റജബ് മാസത്തിലെ അറവും റസൂൽ(സ) നിരോധിച്ചിരിക്കുന്നു. (ബു,മു,ദ,ന,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','د','ن','جه']::text[], array['ബു','മു','ദ','ന','ജ']::text[], null, null, 912, 912, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=4 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=4 and b.book_no=17 and h.hadith_no=105), 1, 'وَفِي رِوَايَةٍ: نَهَى رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَنِ الْفَرَعِ وَالْعَتِيرَةِ. (ق,د,ن,جه)', 'മറ്റൊരു നിവേദനം: മൃഗത്തിന്റെ കടിഞ്ഞൂലിനെ അറുക്കലും റജബ് മാസത്തിലെ അറവും റസൂൽ(സ) നിരോധിച്ചിരിക്കുന്നു. (ബു,മു,ദ,ന,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 106, 'عَنْ شُعَيْبِ بْنِ مُحَمَّدِ بْنِ عَبْدِ اللهِ بْنِ عَمْرٍو، وَزَيْدِ بْنِ أَسْلَمَ: قَالُوا: يَا رَسُولَ اللهِ، الْفَرَعُ؟ قَالَ: "حَقٌّ، فَإِنْ تَرَكْتَهُ حَتَّى يَكُونَ بَكْرًا، فَتَحْمِلَ عَلَيْهِ فِي سَبِيلِ اللهِ، أَوْ تُعْطِيَهُ أَرْمَلَةً، خَيْرٌ مِنْ أَنْ تَذْبَحَهُ فَيَلْصَقَ لَحْمُهُ بِوَبَرِهِ، فَتُكْفِئَ إِنَاءَكَ وَتُولِهَ نَاقَتَكَ". قَالُوا: يَا رَسُولَ اللهِ، فَالْعَتِيرَةُ؟ قَالَ: "الْعَتِيرَةُ حَقٌّ". (ن)', 'ശുഐബുബ്നു മുഹമ്മദിബ്നു അബ്ദില്ലാഹിബ്നി അംറ്(റ), സൈദുബ്നു അസ്ലം(റ): അവർ ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, മൃഗത്തിന്റെ കടിഞ്ഞൂലിനെ അറുക്കുന്നതിനെക്കുറിച്ച് എന്താണങ്ങ് പറയുന്നത്? അവിടുന്ന് പറഞ്ഞു: "അത് ബാധ്യതയാണ്. ചെറു പ്രായമുള്ള ഒരു ഒട്ടകമാകുന്നതുവരെ നീയതിനെ വിടുകയും ശേഷം അല്ലാഹുവിന്റെ മാർഗത്തിലുള്ള പോരാട്ടത്തിനായി അതിനെ ഉപയോഗിക്കുകയും ചെയ്യൽ, അല്ലെങ്കിൽ: ഒരു വിധവക്ക് നീയതിനെ നൽകൽ, നീയതിനെ അറുക്കുകയും അതിന്റെ മാംസം അതിന്റെ രോമത്തോട് ഒട്ടിപ്പിടിച്ച് കിടക്കുകയും നിന്റെ (പാൽ) പാത്രം നീ കമിഴ്ത്തി വെക്കുകയും നിന്റെ ഒട്ടകത്തെ വേദനിപ്പിക്കുകയും ചെയ്യുന്നതിനേക്കാൾ ഉത്തമമാണ്. അവർ ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, അപ്പോൾ റജബ് മാസത്തിലെ അറവോ? റസൂൽ(സ) പറഞ്ഞു: റജബിലെ അറവ് ബാധ്യതയാണ്. (ന)', 'شُعَيْبِ بْنِ مُحَمَّدِ بْنِ عَبْدِ اللهِ بْنِ عَمْرٍو، وَزَيْدِ بْنِ أَسْلَمَ', 'ശുഐബുബ്നു മുഹമ്മദിബ്നു അബ്ദില്ലാഹിബ്നി അംറ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 912, 912, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=4 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 107, 'عَنِ الْحَارِثِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُ: أَنَّهُ لَقِيَ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي حَجَّةِ الْوَدَاعِ وَهُوَ عَلَى نَاقَتِهِ الْعَضْبَاءِ، فَأَتَيْتُهُ مِنْ أَحَدِ شِقَّيْهِ فَقُلْتُ: يَا رَسُولَ اللهِ، بِأَبِي أَنْتَ وَأُمِّي، اسْتَغْفِرْ لِي. فَقَالَ: "غَفَرَ اللهُ لَكُمْ". ثُمَّ أَتَيْتُهُ مِنَ الشِّقِّ الْآخَرِ، أَرْجُو أَنْ يَخُصَّنِي دُونَهُمْ، فَقُلْتُ: يَا رَسُولَ اللهِ، اسْتَغْفِرْ لِي. فَقَالَ بِيَدِهِ: "غَفَرَ اللهُ لَكُمْ". فَقَالَ رَجُلٌ مِنَ النَّاسِ: يَا رَسُولَ اللهِ، الْعَتَائِرُ وَالْفَرَائِعُ؟ قَالَ: "مَنْ شَاءَ عَتَرَ وَمَنْ شَاءَ لَمْ يَعْتِرْ، وَمَنْ شَاءَ فَرَّعَ وَمَنْ شَاءَ لَمْ يُفَرِّعْ. فِي الْغَنَمِ أُضْحِيَّتُهَا". وَقَبَضَ أَصَابِعَهُ إِلَّا وَاحِدَةً. (ن)', 'ഹാരിസുബ്നു അംറ്(റ): അദ്ദേഹം ഹജ്ജത്തുൽ വിദാഇൽ വെച്ച് റസൂൽ(സ)യെ, അവിടുത്തെ ചെവി കീറിയ ഒട്ടകപ്പുറത്തിരിക്കുന്നതായി കണ്ടുമുട്ടി. ഞാൻ റസൂൽ(സ)യുടെ ഒരു ഭാഗത്തിലൂടെ ചെന്ന് അവിടുത്തോട് പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, എന്റെ പിതാവും മാതാവും അങ്ങേക്ക് ദണ്ണമാണ്. എനിക്ക് വേണ്ടി അങ്ങ് പാപമോചനത്തെ തേടിയാലും. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹു നിങ്ങൾക്കെല്ലാവർക്കും പൊറുത്തുതരട്ടെ." മറ്റുള്ളവരെക്കാൾ അവിടുന്നെന്നെ പ്രത്യേകമാക്കണമെന്ന് ആഗ്രഹിച്ചുകൊണ്ട് നബി(സ)യുടെ മറ്റേ ഭാഗത്തിലൂടെ ചെന്നുകൊണ്ട് ഞാൻ പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, എനിക്ക് വേണ്ടി അങ്ങ് പാപമോചനത്തെ തേടിയാലും. അപ്പോൾ കൈകൊണ്ട് ആംഗ്യം കാണിച്ചുകൊണ്ട് അവിടുന്ന് പറഞ്ഞു: "അല്ലാഹു നിങ്ങൾക്കെല്ലാവർക്കും പൊറുത്തുതരട്ടെ." അപ്പോൾ ജനങ്ങളിൽ നിന്നൊരാൾ ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, റജബ് മാസത്തിലെ അറവിനെക്കുറിച്ചും മൃഗത്തിന്റെ കടിഞ്ഞൂലിനെ അറുക്കുന്നതിനെക്കുറിച്ചും അവിടുന്നെന്താണ് പറയുന്നത്? റസൂൽ(സ) പറഞ്ഞു: "റജബ് മാസത്തിൽ അറുക്കാനുദ്ദേശിക്കുന്നവർ അറുക്കട്ടെ. ഉദ്ദേശിക്കാത്തവർ അറുക്കാതിരിക്കുകയും ചെയ്യട്ടെ. മൃഗത്തിന്റെ കടിഞ്ഞൂലിനെ അറുക്കാനുദ്ദേശിക്കുന്നവർ അറുക്കട്ടെ. ഉദ്ദേശിക്കാത്തവർ അറുക്കാതിരിക്കുകയും ചെയ്യട്ടെ. ആടുകളിൽ അതിന്റെ ഉള്ഹിയ്യത്തുണ്ട്." അവിടുന്ന് തന്റെ ഒന്നൊഴികെയുള്ള മറ്റെല്ലാ വിരലുകളും കൂട്ടിപ്പിടിച്ചു. (ന)', 'الْحَارِثِ بْنِ عَمْرٍو', 'ഹാരിസുബ്നു അംറ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 912, 913, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=4 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 108, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: أَمَرَنَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مِنْ كُلِّ خَمْسِينَ شَاةً شَاةً. قَالَ أَبُو دَاوُدَ: قَالَ بَعْضُهُمُ: الْفَرَعُ أَوَّلُ مَا تُنْتِجُ الْإِبِلُ، كَانُوا يَذْبَحُونَهُ لِطَوَاغِيتِهِمْ، ثُمَّ يَأْكُلُونَهُ، وَيُلْقَى جِلْدُهُ عَلَى الشَّجَرِ. وَالْعَتِيرَةُ: فِي الْعَشْرِ الْأُوَلِ مِنْ رَجَبٍ. (خ,د)', 'ആഇശ(റ): ഓരോ അൻപത് ആടുകളിൽ നിന്നും ഓരോ ആടിനെ വീതം അറുക്കാൻ റസൂൽ(സ) ഞങ്ങളോട് കൽപിച്ചു.
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 109, 'عَنْ نُبَيْشَةَ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِنِّي كُنْتُ نَهَيْتُكُمْ عَنْ لُحُومِ الْأَضَاحِيِّ فَوْقَ ثَلَاثٍ كَيْمَا تَسَعَكُمْ، فَقَدْ جَاءَ اللهُ عَزَّ وَجَلَّ بِالْخَيْرِ، فَكُلُوا وَتَصَدَّقُوا وَادَّخِرُوا، وَإِنَّ هَذِهِ الْأَيَّامَ أَيَّامُ أَكْلٍ وَشُرْبٍ وَذِكْرِ اللهِ عَزَّ وَجَلَّ". فَقَالَ رَجُلٌ: إِنَّا كُنَّا نَعْتِرُ عَتِيرَةً فِي الْجَاهِلِيَّةِ فِي رَجَبٍ، فَمَا تَأْمُرُنَا؟ قَالَ: "اذْبَحُوا لِلَّهِ عَزَّ وَجَلَّ فِي أَيِّ شَهْرٍ مَا كَانَ، وَبَرُّوا اللهَ عَزَّ وَجَلَّ وَأَطْعِمُوا". فَقَالَ رَجُلٌ: يَا رَسُولَ اللهِ، إِنَّا كُنَّا نُفْرِعُ فَرَعًا فِي الْجَاهِلِيَّةِ، فَمَا تَأْمُرُنَا؟ قَالَ: فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "فِي كُلِّ سَائِمَةٍ مِنَ الْغَنَمِ فَرَعٌ، تَغْذُوهُ غَنَمُكَ، حَتَّى إِذَا اسْتَحْمَلَ ذَبَحْتَهُ وَتَصَدَّقْتَ بِلَحْمِهِ عَلَى ابْنِ السَّبِيلِ، فَإِنَّ ذَلِكَ هُوَ خَيْرٌ". (د,ن,جه)', 'നുബൈശത്(റ): റസൂൽ(സ) പറഞ്ഞു: "ഉള്ഹിയ്യത്തിന്റെ മാംസം നിങ്ങൾക്കെല്ലാവർക്കും ലഭിക്കാൻ വേണ്ടി, മൂന്ന് ദിവസത്തിന് ശേഷം അത് ഭക്ഷിക്കുന്നത് ഞാൻ വിലക്കിയിരുന്നു. തീർച്ചയായും (ഇപ്പോൾ) അല്ലാഹു നന്മ കൊണ്ടുവന്നിരിക്കുന്നു. അതിനാൽ നിങ്ങൾ ഭക്ഷിക്കുകയും ദാനം ചെയ്യുകയും സൂക്ഷിച്ചുവെക്കുകയും ചെയ്യുക. നിശ്ചയം, ഈ ദിനങ്ങൾ തീറ്റയുടെയും കുടിയുടെയും ദൈവസ്മരണയുടെയും ദിനങ്ങളാണ്." അപ്പോൾ ഒരാൾ ചോദിച്ചു: നിശ്ചയം, ജാഹിലിയ്യാ കാലത്ത് റജബ് മാസത്തിൽ ഞങ്ങൾ അറവ് നടത്താറുണ്ടായിരുന്നു. അങ്ങെന്താണ് ഞങ്ങളോട് കൽപിക്കുന്നത്? അവിടുന്ന് പറഞ്ഞു: "ഏത് മാസത്തിലാണെങ്കിലും അല്ലാഹുവിന് വേണ്ടി നിങ്ങൾ അറുക്കുക. അല്ലാഹുവിനെ നിങ്ങൾ അനുസരിക്കുക, നിങ്ങൾ (മറ്റുള്ളവരെ) ഭക്ഷിപ്പിക്കുക." അപ്പോൾ ഒരാൾ ചോദിച്ചു: അല്ലാഹുവിന്റെ ദൂതരേ, ജാഹിലിയ്യാ കാലത്ത് ഞങ്ങൾ മൃഗങ്ങളുടെ കടിഞ്ഞൂലിനെ അറുക്കാറുണ്ടായിരുന്നു. അങ്ങെന്താണ് ഞങ്ങളോട് കൽപിക്കുന്നത്? അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "ആട്ടിൻപറ്റത്തിൽ നിന്നുള്ള ഓരോ കാലിക്കും കടിഞ്ഞൂലുണ്ട് (അതിനെ അറുക്കേണ്ടതാണ്). നിന്റെ ആട് അതിനെ തീറ്റിപ്പോറ്റണം. അങ്ങനെ ഭാരം ചുമക്കാൻ കഴിയുന്ന പ്രായമായാൽ നീയതിനെ അറുക്കുകയും അതിന്റെ മാംസം യാത്രക്കാർക്ക് നൽകുകയും വേണം. കാരണം, നിശ്ചയം ഇക്കാര്യം നന്മയാണ്." (ദ,ന,ജ)', 'نُبَيْشَةَ', 'നുബൈശത്(റ)', null, null, array['د','ن','جه']::text[], array['ദ','ന','ജ']::text[], null, null, 913, 914, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=4 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 110, 'عَنْ أَبِي رَزِينٍ لَقِيطِ بْنِ عَامِرٍ الْعُقَيْلِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: قُلْتُ: يَا رَسُولَ اللهِ، إِنَّا كُنَّا نَذْبَحُ ذَبَائِحَ فِي الْجَاهِلِيَّةِ فِي رَجَبٍ، فَنَأْكُلُ وَنُطْعِمُ مَنْ جَاءَنَا؟ فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا بَأْسَ بِهِ". (ن)', 'അബീറസീൻ ലഖീഥുബ്നു ആമിറുൽ ഉഖൈലി(റ): ഞാൻ പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, നിശ്ചയം ജാഹിലിയ്യാ കാലത്ത് ഞങ്ങൾ റജബ് മാസത്തിൽ അറവ് നടത്തുകയും ഭക്ഷിക്കുകയും ഞങ്ങളുടെ അടുത്തേക്ക് വരുന്നവരെ ഭക്ഷിപ്പിക്കുകയും ചെയ്തിരുന്നു. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "അതുകൊണ്ട് ഒരു കുഴപ്പവുമില്ല." (ന)', 'أَبِي رَزِينٍ لَقِيطِ بْنِ عَامِرٍ الْعُقَيْلِيِّ', 'അബീറസീൻ ലഖീഥുബ്നു ആമിറുൽ ഉഖൈലി(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 914, 914, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=4 and b.book_no=17 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
